def _render_company_switch_confirm(*, key_prefix: str = "co_sw") -> None:
    """Page-level confirm — popover closes on rerun so this must live outside it."""
    if not st.session_state.get("_confirm_company_switch"):
        return
    _mobile_open_surface("company_switch_confirm")
    _target = st.session_state.get("_switch_target_company_id")
    _warn = (
        _t("header.switch_warning_named", name=_company_name_plain(
            next(
                (n for cid, n, _ in st.session_state.get("_user_company_memberships", []) if cid == _target),
                "",
            )
        ))
        if _target else _t("header.switch_warning")
    )
    with st.container(key=f"{key_prefix}_confirm_shell"):
        st.markdown('<div class="erp-co-switch-confirm-host"></div>', unsafe_allow_html=True)
        st.warning(_warn, icon="⚠️")
        _sc1, _sc2 = st.columns(2)
        if _sc1.button(
            _t("header.continue"),
            key=f"{key_prefix}_ok",
            use_container_width=True,
            type="primary",
        ):
            _expand = st.session_state.pop("_hdr_open_create_after_picker", False)
            _target = st.session_state.pop("_switch_target_company_id", None)
            st.session_state.pop("_confirm_company_switch", None)
            st.session_state.pop("mob_profile_open", None)
            st.session_state.pop("mob_co_switch_open", None)
            if _target:
                _u = _current_user()
                if _u:
                    with get_session() as _sw_session:
                        _cnt = st.session_state.get("active_company_membership_count")
                        if _activate_company_in_session(
                            _sw_session, _u["id"], _target, membership_count=_cnt
                        ):
                            st.rerun()
            if _expand:
                _start_create_company_wizard()
            else:
                _go_to_company_picker()
        if _sc2.button(
            _t("common.cancel"),
            key=f"{key_prefix}_no",
            use_container_width=True,
        ):
            _mobile_clear_company_switch_confirm()
            st.rerun()


def _render_hdr_toolbar(user: dict, *, slot: str) -> None:
    """Notifications + profile popover (slot: primary | mobile_left | desktop_right)."""
    notif       = _notif_counts(user.get("id", 1))
    notif_total = notif["total"]
    _display    = user.get("display_name") or user.get("username", "User")
    _initials   = user_initials(user=user)
    _nav_role   = _current_company_role() or user.get("role", "viewer")
    _role_lbl   = html.escape(_company_role_label(_nav_role))
    _legacy_desktop = slot == "desktop_right"
    if _legacy_desktop:
        _tb_key = "hdr_toolbar_row"
        _pfx = ""
        _k = lambda stem: stem  # noqa: E731 — pre-mobile desktop widget keys
    else:
        _tb_key = f"hdr_toolbar_{slot}"
        _pfx = {"mobile_left": "m"}.get(slot, "p")
        _k = lambda stem: f"{stem}_{_pfx}"  # noqa: E731
    _h_align = "right" if _legacy_desktop else "left"

    st.markdown(
        f'<div class="erp-hdr-toolbar-slot erp-hdr-toolbar-{slot}"></div>',
        unsafe_allow_html=True,
    )
    with st.container(
        horizontal=True,
        gap="small",
        vertical_alignment="center",
        horizontal_alignment=_h_align,
        width="content",
        key=_tb_key,
    ):
        st.markdown(
            f'<span class="erp-hdr-role-marker erp-hdr-role-{_nav_role}'
            f'{" erp-hdr-notif-active" if notif_total > 0 else ""}"></span>',
            unsafe_allow_html=True,
        )
        _bell_lbl = (
            "🔔"
            if _is_mobile_ui()
            else (f"🔔{notif_total}" if notif_total > 0 else "🔔")
        )
        _notif_key = "hdr_notif_pop" if _legacy_desktop else _k("hdr_notif")
        with st.popover(_bell_lbl, help=_t("header.notifications_help"), key=_notif_key):
            st.markdown(_t("header.notifications_title"))
            st.divider()
            if notif_total == 0:
                st.caption(_t("dash.no_alerts"))
            else:
                if notif["overdue_ar"] > 0:
                    _c1, _c2 = st.columns([5, 2])
                    _c1.markdown(
                        _t("notif.line.overdue_ar", count=notif["overdue_ar"])
                    )
                    _ar_key = "notif_ar_btn" if _legacy_desktop else _k("notif_ar")
                    if _c2.button(_t("notif.view"), key=_ar_key):
                        _mobile_close_app_surfaces()
                        st.session_state["nav_selection"] = NAV_RECEIVABLES
                        st.rerun()
                if notif["overdue_ap"] > 0:
                    _c1, _c2 = st.columns([5, 2])
                    _c1.markdown(
                        _t("notif.line.overdue_ap", count=notif["overdue_ap"])
                    )
                    _ap_key = "notif_ap_btn" if _legacy_desktop else _k("notif_ap")
                    if _c2.button(_t("notif.view"), key=_ap_key):
                        _mobile_close_app_surfaces()
                        st.session_state["nav_selection"] = NAV_PAYABLES
                        st.rerun()
                if notif["low_stock"] > 0:
                    _c1, _c2 = st.columns([5, 2])
                    _c1.markdown(
                        _t("notif.line.low_stock", count=notif["low_stock"])
                    )
                    _ls_key = "notif_ls_btn" if _legacy_desktop else _k("notif_ls")
                    if _c2.button(_t("notif.view"), key=_ls_key):
                        _mobile_close_app_surfaces()
                        st.session_state["nav_selection"] = NAV_INVENTORY
                        st.rerun()
                if notif["backup"] > 0:
                    st.warning(_t("backup.reminder_48h"), icon="⚠️")
            st.divider()
            _notif_all_key = "notif_view_all" if _legacy_desktop else _k("notif_all")
            if st.button(_t("notif.view_all"), key=_notif_all_key, use_container_width=True):
                _mobile_close_app_surfaces()
                st.session_state["nav_selection"] = NAV_MY_ACCOUNT
                st.session_state["my_account_tab"] = 3
                st.rerun()

        if _legacy_desktop:
            _theme_mode = st.session_state.get("theme_mode", "system")
            _tog = "☀️" if _theme_mode == "dark" else "🌙"
            if st.button(_tog, key="hdr_dark_toggle", help=_t("header.toggle_theme")):
                _flip_header_theme(user)

        if _is_mobile_ui():
            if st.button(
                "👤",
                key="hdr_mobile_profile_btn",
                help=_t("header.my_account"),
            ):
                _mobile_open_surface("profile")
                st.rerun()
        else:
            with st.popover(_initials, help=_t("header.my_account"), key="hdr_profile_pop"):
                _prof_memberships = st.session_state.get("_user_company_memberships") or []
