        ("purchases",           "native_amount REAL"),
        # Step 6 — partial payable payments
        ("payables",            "paid_amount REAL DEFAULT 0"),
        ("payables",            "balance REAL"),
        # Step 10 — currency on journal lines
        ("journal_entry_lines", "currency TEXT"),
