def _at_dev_log_submit(
    phase: str,
    *,
    txn_type: str = "",
    ctx: dict | None = None,
    amount=None,
    blocked: str | None = None,
    reached_save: bool = False,
) -> None:
    if not DEV_MODE:
        return
    cat_name = (ctx or {}).get("at_cat").name if (ctx or {}).get("at_cat") else None
    parts = [
        f"AT[{phase}]",
        f"txn_type={txn_type}",
        f"pm={(ctx or {}).get('at_payment_method')}",
        f"amount={amount}",
        f"cat_id={(ctx or {}).get('at_cat_id')}",
        f"cat_name={cat_name}",
        f"subcat_id={st.session_state.get('mob_at_subcat_id')}",
        f"subcat_name={(ctx or {}).get('at_subcat_name')}",
        f"at_last_cat_id={st.session_state.get('at_last_cat_id')}",
    ]
    if blocked:
        parts.append(f"blocked={blocked}")
    if reached_save:
        parts.append("reached_save=True")
    logging.warning(" ".join(str(p) for p in parts))


def _save_and_post_expense_record(
    session,
    record: ExpenseRecord,
    *,
    category: str,
    payment_method: str,
    credit_card_account_id: int | None = None,
) -> tuple[bool, str | None]:
    """Create expense row, post GL 2110 + CC sub-ledger. Returns (ok, error_message)."""
    if record.company_id is None:
        record.company_id = _current_company_id()
    cc_id = None
    if payment_method == _COMPANY_CC_METHOD:
        cc_id = _resolve_submit_company_cc_card_id(
            session, payment_method, credit_card_account_id
        )
        cc_err = _validate_company_cc_card(session, payment_method, cc_id)
        if cc_err:
            return False, cc_err
        record.credit_card_account_id = cc_id
    session.add(record)
    session.flush()
    try:
        post_expense(
            session,
            record.id,
            record.amount,
            record.date,
            category,
            payment_method=payment_method,
            credit_card_account_id=cc_id,
        )
    except ValueError as exc:
        session.rollback()
        return False, str(exc)
    session.commit()
    return True, None


def _staff_capture_post_expense_draft(session, view) -> "sc.ExpensePostResult":
    """TD-SC-01 posting seam — wire approved expense draft to existing save/post path."""
    from services import staff_capture as sc

    cat = session.get(TransactionCategory, view.tx_category_id) if view.tx_category_id else None
    sub = (
        session.get(TransactionSubcategory, view.tx_subcategory_id)
        if view.tx_subcategory_id
        else None
    )
    expense_type = cat.name if cat else "Other"
    gl_category = (sub.name if sub else None) or expense_type
    record = ExpenseRecord(
        date=view.date,
        expense_type=expense_type,
        category=gl_category,
        description=view.description or "",
        amount=view.amount,
        payment_method=view.payment_method,
        gross_salary=view.amount,
        deductions=0.0,
        net_salary=view.amount,
        tx_category_id=view.tx_category_id,
        tx_subcategory_id=view.tx_subcategory_id,
        created_by_id=view.created_by_id,
        currency=view.currency,
        fx_rate=1.0,
        native_amount=view.amount,
        company_id=view.company_id,
    )
    ok, err = _save_and_post_expense_record(
        session,
        record,
        category=gl_category,
        payment_method=view.payment_method,
    )
    if not ok:
        return sc.ExpensePostResult(expense_record_id=None, error=err or "Posting failed.")
    return sc.ExpensePostResult(expense_record_id=record.id)


def _validate_company_cc_payment(session, payment_method: str | None) -> str | None:
    """Return an error message if company CC is requested while disabled; else None."""
    if (payment_method or "") == _COMPANY_CC_METHOD and not _company_card_on(session):
        return _t("form.err.company_cc_disabled")
    return None


def _resolve_submit_company_cc_card_id(
    session,
    payment_method: str | None,
    explicit_id: int | None = None,
) -> int | None:
    """Resolve company CC account at save time (auto-pick when one active card)."""
    if (payment_method or "") != _COMPANY_CC_METHOD:
        return None
    cid = _current_company_id()
    if cid is None:
        return None
    try:
        return resolve_company_credit_card_account_id(session, cid, explicit_id)
    except CompanyCardError:
        return None


def _validate_company_cc_card(
    session, payment_method: str | None, credit_card_account_id: int | None = None
) -> str | None:
    """Validate company CC toggle, card accounts, and multi-card selection."""
    err = _validate_company_cc_payment(session, payment_method)
    if err:
        return err
    if (payment_method or "") != _COMPANY_CC_METHOD:
        return None
    cid = _current_company_id()
    if cid is None:
        return _t("form.err.company_cc_no_cards")
    try:
        resolve_company_credit_card_account_id(session, cid, credit_card_account_id)
    except CompanyCardError as exc:
        return str(exc)
    return None


