def _has_active_partners(session) -> bool:
    """True when the company uses partner equity (partnership), not sole-owner equity."""
    return cq(session, Partner).filter_by(is_active=True).count() > 0


def _has_active_workers(session) -> bool:
    return cq(session, Worker).filter_by(is_active=True).count() > 0


def _record_named_bank_movement(
    session,
    bank_accounts: list,
    acct_name: str | None,
    *,
    amount: float,
    date: datetime.date,
    description: str,
    txn_type: str,
) -> BankAccount | None:
    """Update a named BankAccount balance and append a BankTransaction row."""
    if not acct_name or not bank_accounts or amount <= 0:
        return None
    from reconciliation.company_card import apply_account_balance_delta

    ba = next((a for a in bank_accounts if a.name == acct_name), None)
    if not ba:
        return None
    apply_account_balance_delta(ba, txn_type, amount)
    session.add(
        BankTransaction(
            account_id=ba.id,
            date=date,
            amount=amount,
            type=txn_type,
            description=description,
        )
    )
    session.add(ba)
    return ba


def _bank_account_for_payment(
    session, payment_method: str, *, currency: str | None = None,
    preferred_name: str | None = None,
) -> BankAccount | None:
    """Pick a BankAccount row for worker payroll / bank-txn posting."""
    ba, _err = _bank_account_for_worker_payment(
        session,
        payment_method,
        currency=currency,
        preferred_name=preferred_name,
    )
    return ba


def _bank_account_for_worker_payment(
    session,
    payment_method: str,
    *,
    currency: str | None = None,
    preferred_name: str | None = None,
) -> tuple[BankAccount | None, str | None]:
    """Resolve bank sub-ledger row for worker salary/advance with setup-friendly errors."""
    ccy = currency or load_settings().get("currency", "TRY")
    pm = (payment_method or "").lower()
    accounts = (
        cq(session, BankAccount).filter_by(is_active=True).order_by(BankAccount.name).all()
    )
    if preferred_name:
        ba = next((a for a in accounts if a.name == preferred_name), None)
        if ba:
            if pm == "cash" and "cash" not in (ba.name or "").lower():
                return None, _t("txn.worker_cash_account_mismatch")
            if pm == "bank" and "cash" in (ba.name or "").lower():
                return None, _t("txn.worker_bank_account_mismatch")
            return ba, None
    if not accounts:
        gl_name = "Cash" if pm == "cash" else "Bank"
        if get_account_by_name(session, gl_name, currency=ccy):
            return None, _t("txn.worker_setup_subledger", account=gl_name)
        return None, _t("form.no_bank_accounts")
    if pm == "cash":
        for a in accounts:
            if "cash" in (a.name or "").lower():
                return a, None
        if get_account_by_name(session, "Cash", currency=ccy):
            return None, _t("txn.worker_cash_subledger_missing")
        return None, _t("txn.worker_cash_gl_missing")
    for a in accounts:
        if "cash" not in (a.name or "").lower() and (a.currency or "TRY") == ccy:
            return a, None
    for a in accounts:
        if "cash" not in (a.name or "").lower():
            return a, None
    return None, _t("txn.worker_bank_subledger_missing")


