# ---------------------------------------------------------------------------
# Concept C — new picker sheets for txn_type / payment / date / currency
# ---------------------------------------------------------------------------

# Type display labels for the Row 1 type button and the type picker sheet.
_MOB_AT_C_TYPE_ROWS = (
    (0, "Sale",              "sale"),
    (1, "Expense",           "expense"),
    (2, "Purchase",          "purchase"),
    (3, "Supplier Payment",  "supplier"),
    (4, "Customer Payment",  "customer"),
    (5, "Bank Transaction",  "bank"),
    (_MOB_AT_SALARY_IDX, "Salary", "salary"),
)

# Dot colours per type key (matches design spec).
_MOB_AT_C_TYPE_COLOUR: dict[str, str] = {
    "sale":     "#10b981",
    "expense":  "#f59e0b",
    "purchase": "#8b5cf6",
    "supplier": "#ec4899",
    "customer": "#06b6d4",
    "bank":     "#64748b",
    "salary":   "#f97316",
}


def _mob_at_c_current_type_key() -> str:
    """Return the short type key for the current at_type_idx / mob_at_more_idx."""
    if _mob_at_is_salary_mode():
        return "salary"
    idx = st.session_state.get("at_type_idx", 0)
    for row_idx, _label, key in _MOB_AT_C_TYPE_ROWS:
        if row_idx == idx:
            return key
    return "sale"


def _mob_at_c_type_label() -> str:
    key = _mob_at_c_current_type_key()
    for _idx, label, k in _MOB_AT_C_TYPE_ROWS:
        if k == key:
            return label
    return "Sale"


def _mob_at_c_apply_type(idx: int) -> None:
    """Set at_type_idx and sync mob_at_tab / mob_at_more_idx from a Concept C type selection."""
    st.session_state["at_type_idx"] = idx
    if idx < 3:
        st.session_state["mob_at_tab"] = idx
    else:
        st.session_state["mob_at_tab"] = 3
        st.session_state["mob_at_more_idx"] = idx
    # Clear category when type changes
    for k in (
        "mob_at_cat_id",
        "mob_at_subcat_id",
        "mob_at_cat_name",
        "at_cat",
        "at_subcat",
        "at_last_cat_id",
    ):
        st.session_state.pop(k, None)


def _mob_at_render_txn_type_picker_sheet() -> bool:
    """Concept C — bottom sheet to pick transaction type."""
    with st.container(border=False, key="erp_mob_at_picker_sheet"):
        st.markdown('<div class="erp-mob-at-picker-grab"></div>', unsafe_allow_html=True)
        if _mob_at_render_picker_hdr(_tf("txn.mob.pick_type", "Transaction Type")):
            return True

        current_key = _mob_at_c_current_type_key()
        with st.container(border=False, key="mob_at_picker_grid"):
            for row_idx, label, key in _MOB_AT_C_TYPE_ROWS:
                colour = _MOB_AT_C_TYPE_COLOUR.get(key, "#94a3b8")
                is_active = key == current_key
                # st.button does not render HTML — use markdown dot + plain text button
                dc, bc = st.columns([0.06, 1], gap="small")
                with dc:
                    st.markdown(
                        f'<div class="erp-mob-at-cat-dot" style="background:{colour}"></div>',
                        unsafe_allow_html=True,
                    )
                with bc:
                    if st.button(
                        label,
                        key=f"mob_at_pick_type_{key}",
                        use_container_width=True,
                        type="primary" if is_active else "secondary",
                    ):
                        _mob_at_c_apply_type(row_idx)
                        _mob_at_close_picker()
                        return True
    return False


def _mob_at_weekday_date_detail(d: datetime.date) -> str:
    """Weekday + short date for date-sheet quick-choice labels (e.g. 'Mon 9 Jun')."""
    try:
        return f"{d.strftime('%a')} {d.strftime('%-d %b')}"
    except ValueError:
        return f"{d.strftime('%a')} {d.strftime('%d %b')}"


def _mob_at_date_quick_label(i18n_key: str, fallback: str, d: datetime.date) -> str:
    detail = _mob_at_weekday_date_detail(d)
    return _tf(i18n_key, fallback, detail=detail)


def _mob_at_set_date_choice(
    chosen: datetime.date, *, follows_today: bool
) -> None:
    st.session_state["at_date"] = chosen
    st.session_state["at_date_follows_today"] = follows_today
    st.session_state.pop("mob_at_date_custom", None)
    _at_defer_date_text_display(chosen)


def _mob_at_apply_date_follow_today() -> None:
    """DATE-01 — roll at_date forward when user left it pinned to Today."""
    if st.session_state.get("at_date_follows_today", True) is False:
        return
    st.session_state["at_date"] = datetime.date.today()


def _mob_at_date_is_backdated() -> bool:
    d = st.session_state.get("at_date", datetime.date.today())
    return isinstance(d, datetime.date) and d != datetime.date.today()


def _mob_at_render_date_closed_period_notice(session, entry_date: datetime.date) -> None:
    """Courtesy closed-period warning (posting engine remains final authority)."""
    blocked = _entry_date_posting_blocked(session, entry_date)
    if blocked:
        st.caption(f"⚠️ {blocked}")


def _mob_at_render_date_picker_sheet(session) -> bool:
    """Mobile date picker — Today / Yesterday / Custom (no Streamlit calendar popup)."""
    today = datetime.date.today()
    yesterday = today - datetime.timedelta(days=1)
    current = st.session_state.get("at_date", today)
    if not isinstance(current, datetime.date):
        current = today
    custom_open = bool(st.session_state.get("mob_at_date_custom")) or (
        current not in (today, yesterday)
    )

    with st.container(border=False, key="erp_mob_at_picker_sheet"):
        st.markdown('<div class="erp-mob-at-picker-grab"></div>', unsafe_allow_html=True)
        if _mob_at_render_picker_hdr(_tf("txn.mob.pick_date", "Date")):
            return True

        with st.container(border=False, key="mob_at_picker_grid"):
            if st.button(
                _mob_at_date_quick_label(
                    "txn.mob.date_today_choice", "Today · {detail}", today
                ),
                key="mob_at_pick_date_today",
                use_container_width=True,
                type="primary" if current == today and not custom_open else "secondary",
            ):
                _mob_at_set_date_choice(today, follows_today=True)
                _mob_at_close_picker()
                return True
            if st.button(
                _mob_at_date_quick_label(
                    "txn.mob.date_yesterday_choice", "Yesterday · {detail}", yesterday
                ),
                key="mob_at_pick_date_yesterday",
                use_container_width=True,
                type="primary" if current == yesterday and not custom_open else "secondary",
            ):
                _mob_at_set_date_choice(yesterday, follows_today=False)
                _mob_at_close_picker()
                return True
            _mob_at_render_date_closed_period_notice(session, yesterday)
            if st.button(
                _tf("txn.mob.date_custom_choice", "Custom date..."),
                key="mob_at_pick_date_custom",
                use_container_width=True,
                type="primary" if custom_open else "secondary",
            ):
                st.session_state["mob_at_date_custom"] = True
                st.session_state["at_date_follows_today"] = False
                st.session_state["mob_at_date_custom_str"] = _format_at_display_date(
                    current
                )
                st.rerun()

        if custom_open:
            date_ui.seed_date_text_key("mob_at_date_custom_str", current)
            date_ui.render_preferred_date_input(
                _tf("txn.mob.date_custom_label", "Date"),
                "mob_at_date_custom_str",
                label_visibility="collapsed",
                invalid_message=_t("txn.date_invalid"),
            )
            if st.button(
                _tf("txn.mob.date_confirm", "✓ Confirm Date"),
                key="mob_at_c_date_confirm",
                use_container_width=True,
                type="primary",
            ):
                parsed = _mob_at_parse_date_text(
                    st.session_state.get("mob_at_date_custom_str", "")
                )
                if parsed is None:
                    st.warning(_t("txn.date_invalid"))
                    return False
                _mob_at_render_date_closed_period_notice(session, parsed)
                _mob_at_set_date_choice(parsed, follows_today=False)
                st.session_state["mob_at_date_custom_str"] = _format_at_display_date(
                    parsed
                )
                _mob_at_close_picker()
                return True
    return False


def _mob_at_render_currency_picker_sheet(currency_default: str) -> bool:
    """Concept C — bottom sheet for currency selection."""
    currencies = CURRENCIES
    current = st.session_state.get("at_currency", currency_default)
    with st.container(border=False, key="erp_mob_at_picker_sheet"):
        st.markdown('<div class="erp-mob-at-picker-grab"></div>', unsafe_allow_html=True)
        if _mob_at_render_picker_hdr(_tf("txn.mob.pick_currency", "Currency")):
            return True

        with st.container(border=False, key="mob_at_picker_grid"):
            ccols = st.columns(len(currencies), gap="small")
            for col, cur in zip(ccols, currencies):
                is_active = cur == current
                if col.button(
                    cur,
                    key=f"mob_at_pick_cur_{cur}",
                    use_container_width=True,
                    type="primary" if is_active else "secondary",
                ):
                    st.session_state["at_currency"] = cur
                    _mob_at_close_picker()
                    return True
    return False


# ---------------------------------------------------------------------------
# End Concept C picker sheets
# ---------------------------------------------------------------------------


def _mob_at_render_picker_sheet(
    session,
    *,
    picker_kind: str,
    vendors: list,
    open_sales: list,
    bank_accounts: list,
    currency_default: str,
) -> bool:
    """In-panel picker content (replaces AT controls while open). Returns True if rerun needed."""
    # Concept C new picker modes
    if picker_kind == "txn_type":
        return _mob_at_render_txn_type_picker_sheet()
    if picker_kind == "date":
        return _mob_at_render_date_picker_sheet(session)
    if picker_kind == "currency":
        return _mob_at_render_currency_picker_sheet(currency_default)
    # Existing picker modes
    if picker_kind == "vendor":
        return _mob_at_render_vendor_picker_sheet(session, vendors)
    if picker_kind == "invoice":
        return _mob_at_render_invoice_picker_sheet(open_sales)
    if picker_kind == "payable":
        return _mob_at_render_payable_picker_sheet(
            session, vendors, currency_default
        )
    if picker_kind == "bank_acct":
        return _mob_at_render_bank_picker_sheet(bank_accounts)
    if picker_kind == "card_bank":
        return _mob_at_render_card_bank_picker_sheet(bank_accounts)
    if picker_kind == "bank_pay":
        return _mob_at_render_bank_pay_picker_sheet(bank_accounts)
    if _mob_at_is_subcat_picker(picker_kind):
        return _mob_at_render_subcategory_picker_sheet(session, picker_kind=picker_kind)
    return _mob_at_render_category_picker_sheet(session, picker_kind=picker_kind)


def _mob_at_tab_to_type_idx(mob_tab: int, more_type_idx: int = 3) -> int:
    return mob_tab if mob_tab < 3 else more_type_idx


def _mob_at_is_salary_mode() -> bool:
    """Salary chip (MORE tab) maps to Expense → Worker → Salary on save."""
    return (
        st.session_state.get("mob_at_tab") == 3
        and st.session_state.get("mob_at_more_idx") == _MOB_AT_SALARY_IDX
    )


def _at_effective_txn_type(type_names: list[str]) -> str:
    """Map at_type_idx to a real posting type (Salary chip uses idx 6 → Expense)."""
    idx = st.session_state.get("at_type_idx", 0)
    if idx == _MOB_AT_SALARY_IDX or _mob_at_is_salary_mode():
        return "Expense"
    if 0 <= idx < len(type_names):
        return type_names[idx]
    return type_names[0] if type_names else "Expense"


def _mob_at_submit_txn_type(type_names: list[str]) -> str:
    return _at_effective_txn_type(type_names)


def _mob_at_amount_display_text(raw: str | None = None) -> str:
    """Formatted amount line for the mobile calculator display."""
    val = raw if raw is not None else st.session_state.get("at_amount_display", "")
    return (val or "") or "0"


def _mob_at_append_amount_digit(digit: str) -> bool:
    """Append/backspace/clear into at_amount_display (mobile keypad). Returns True if buffer changed."""
    cur = st.session_state.get("at_amount_display", "") or ""
    if digit == "bksp":
        if not cur:
            return False
        st.session_state["at_amount_display"] = cur[:-1]
        return True
    if digit == "clr":
        if not cur:
            return False
        st.session_state["at_amount_display"] = ""
        return True
    if digit == ".":
        if "." in cur or "," in cur:
            return False
        st.session_state["at_amount_display"] = cur + "."
        return True
    st.session_state["at_amount_display"] = cur + digit
    return True


