def _at_sync_desktop_type_to_mobile_tabs() -> None:
    """Keep mob_at_tab aligned with desktop at_type_idx (canonical on desktop)."""
    idx = st.session_state.get("at_type_idx", 0)
    if idx <= 2:
        st.session_state["mob_at_tab"] = idx
    else:
        st.session_state["mob_at_tab"] = 3
        st.session_state["mob_at_more_idx"] = idx


def _mob_at_sync_type_from_tab() -> None:
    """Mobile UI: mob_at_tab is canonical and drives at_type_idx."""
    if not st.session_state.get("_erp_mobile_ui", False):
        return
    mob_tab = st.session_state.get("mob_at_tab", 0)
    more_idx = st.session_state.get("mob_at_more_idx", 3)
    st.session_state["at_type_idx"] = _mob_at_tab_to_type_idx(mob_tab, more_idx)
    if _mob_at_is_salary_mode():
        st.session_state["at_expense_mode"] = "worker"
        st.session_state["at_worker_mv_type"] = "Salary"
    elif mob_tab == 1:
        st.session_state["at_expense_mode"] = "general"


def _at_set_flash(level: str, message: str) -> None:
    """Persist New Transaction feedback across st.rerun()."""
    st.session_state["at_flash_level"] = level
    st.session_state["at_flash_message"] = message


def _at_render_flash() -> None:
    level = st.session_state.pop("at_flash_level", None)
    message = st.session_state.pop("at_flash_message", None)
    if not message:
        return
    if level == "success":
        st.success(message)
    elif level == "error":
        st.error(message)
    else:
        st.info(message)


def _mob_at_ensure_defaults(session, txn_type: str, currency_default: str, vendors: list) -> None:
    if "at_date" not in st.session_state:
        st.session_state["at_date"] = datetime.date.today()
        st.session_state["at_date_follows_today"] = True
    st.session_state.setdefault("at_currency", currency_default)
    st.session_state.setdefault("at_notes_field", "")
    st.session_state.setdefault("at_expense_mode", "general")
    st.session_state.setdefault("at_picker_mode", "")
    if txn_type == "Sale":
        st.session_state.setdefault("at_cust", "Walk-in Customer")
    if txn_type in _AT_PM_TXN_TYPES:
        st.session_state.setdefault("at_pm", _at_default_pay_method(session, txn_type))
    if txn_type == "Supplier Payment":
        _at_clear_category_session_state()
    if txn_type == "Bank Transaction":
        st.session_state.setdefault("at_bank_sub", "Deposit")
    _coerce_at_payment_method(session, txn_type)


def _at_gather_submit_fields(
    session,
    txn_type: str,
    currency_default: str,
    vendors: list,
    bank_accounts: list,
    open_sales: list,
) -> dict:
    """Collect submit context from session state (desktop + mobile)."""
    _coerce_at_payment_method(session, txn_type)
    _mob_at_sync_select_widgets()
    date = _at_resolve_submit_date()
    at_notes = st.session_state.get("at_notes_field", "") or ""
    at_payment_method = st.session_state.get("at_pm", "Cash")
    at_fx_rate = float(st.session_state.get("at_fx_rate_val") or 1.0)

    customer_name_val = ""
    if txn_type == "Sale":
        if at_payment_method == "Credit":
            sel = st.session_state.get("at_cust_sel")
            if sel and sel != "— type manually —":
                customer_name_val = sel
            else:
                customer_name_val = st.session_state.get("at_cust", "")
        else:
            customer_name_val = st.session_state.get("at_cust", "Walk-in Customer")

    _vendor_names = [v.name for v in vendors]
    vendor_name_val = _at_normalize_vendor_selection(
        st.session_state.get("at_vendor"), _vendor_names
    )

    at_cat = at_cat_id = at_subcat_name = None
    subcats_list: list = []
    cats: list = []
    if txn_type in ("Expense", "Purchase"):
        cats = (
            cq(session, TransactionCategory)
            .filter_by(transaction_type=txn_type, is_active=True)
            .order_by(TransactionCategory.name)
            .all()
        )

    if txn_type in ("Expense", "Purchase"):
        cid = st.session_state.get("mob_at_cat_id")
        if cid:
            _lc = session.get(TransactionCategory, cid)
            if _lc and _lc.is_active and _lc.transaction_type == txn_type:
                at_cat_id = cid
                at_cat = _lc
        elif st.session_state.get("at_cat") and cats:
            at_cat = next(
                (c for c in cats if c.name == st.session_state["at_cat"]),
                None,
            )
            if at_cat:
                at_cat_id = at_cat.id
        if at_cat_id:
            _mob_at_apply_default_subcategory(session, at_cat_id)

        sid = st.session_state.get("mob_at_subcat_id")
        if sid and at_cat_id:
            sub = session.get(TransactionSubcategory, sid)
            if sub and sub.category_id == at_cat_id:
                at_subcat_name = sub.name
                subcats_list = (
                    cq(session, TransactionSubcategory)
                    .filter_by(category_id=at_cat_id, is_active=True)
                    .order_by(TransactionSubcategory.name)
                    .all()
                )
        elif at_cat_id and st.session_state.get("at_subcat"):
            subcats_list = (
                cq(session, TransactionSubcategory)
                .filter_by(category_id=at_cat_id, is_active=True)
                .order_by(TransactionSubcategory.name)
                .all()
            )
            if st.session_state["at_subcat"] in [s.name for s in subcats_list]:
                at_subcat_name = st.session_state["at_subcat"]

    invoice_choices: list = []
    invoice_choice_val = None
    if txn_type == "Customer Payment" and open_sales:
        invoice_choices = [_at_invoice_choice_label(s) for s in open_sales]
        invoice_choice_val = st.session_state.get("at_inv")
        if invoice_choice_val not in invoice_choices:
            invoice_choice_val = None

    bank_sub = st.session_state.get("at_bank_sub", "Deposit")
    bank_acct_val = st.session_state.get("at_bank_acct") or (
        bank_accounts[0].name if bank_accounts else None
    )
    bank_dest_val = st.session_state.get("at_bank_dest")

    effective_category = ""
    if at_cat:
        effective_category = at_cat.name
    elif st.session_state.get("mob_at_cat_name"):
        effective_category = st.session_state["mob_at_cat_name"]

    return {
        "date": date,
        "at_notes": at_notes,
        "at_payment_method": at_payment_method,
        "at_fx_rate": at_fx_rate,
        "customer_name_val": customer_name_val,
        "vendor_name_val": vendor_name_val,
        "at_cat": at_cat,
        "at_cat_id": at_cat_id,
        "at_subcat_name": at_subcat_name,
        "subcats_list": subcats_list,
        "effective_category": effective_category,
        "invoice_choices": invoice_choices,
        "invoice_choice_val": invoice_choice_val,
        "bank_sub": bank_sub,
        "bank_acct_val": bank_acct_val,
        "bank_dest_val": bank_dest_val,
    }


def _at_process_submit(
    session,
    *,
    currency_default: str,
    vendors: list,
    bank_accounts: list,
    open_sales: list,
    txn_type: str,
    _TYPE_DISPLAY_MAP: dict,
) -> None:
    amount_raw = st.session_state.get("at_amount_display", "")
    amount = _parse_amount_str(amount_raw) if amount_raw else None
    ctx = _at_gather_submit_fields(
        session, txn_type, currency_default, vendors, bank_accounts, open_sales
    )
    _at_dev_log_submit("gather", txn_type=txn_type, ctx=ctx, amount=amount)
    _submit_cc_card_id = _resolve_submit_company_cc_card_id(
        session,
        ctx["at_payment_method"],
        st.session_state.get("at_cc_card_id"),
    )

    at_subcat_id = None
    if ctx["at_subcat_name"] and ctx["subcats_list"]:
        _sub_obj = next((s for s in ctx["subcats_list"] if s.name == ctx["at_subcat_name"]), None)
        at_subcat_id = _sub_obj.id if _sub_obj else None

    _skip_cat = txn_type == "Expense" and (
        _mob_at_is_salary_mode() or st.session_state.get("at_expense_mode") == "worker"
    )
    if txn_type in ("Expense", "Purchase") and not _skip_cat:
        if not ctx["at_cat_id"] and not (
            txn_type == "Expense" and st.session_state.get("mob_at_cat_name")
        ):
            _cat_err = _t("txn.category_required")
            st.error(_cat_err)
            _at_set_flash("error", _cat_err)
            _at_dev_log_submit(
                "validate", txn_type=txn_type, ctx=ctx, amount=amount, blocked="category"
            )
            return
        if ctx["at_cat_id"]:
            _need_subcats = (
                cq(session, TransactionSubcategory)
                .filter_by(category_id=ctx["at_cat_id"], is_active=True)
                .count()
            )
            if _need_subcats and not ctx["at_subcat_name"]:
                _sub_err = _tf("txn.mob.subcategory_required", "Select a subcategory")
                st.error(_sub_err)
                _at_set_flash("error", _sub_err)
                _at_dev_log_submit(
                    "validate", txn_type=txn_type, ctx=ctx, amount=amount, blocked="subcategory"
                )
                return

    if _mob_at_is_salary_mode():
        st.session_state["at_expense_mode"] = "worker"
        st.session_state["at_worker_mv_type"] = "Salary"
        _mob_at_sync_select_widgets()
        st.session_state["at_worker_gross"] = (
            st.session_state.get("mob_at_worker_gross") or ""
        )
        st.session_state["at_worker_ded"] = str(
            st.session_state.get("mob_at_worker_ded") or "0"
        )
        st.session_state["at_worker_adv_rec"] = str(
            st.session_state.get("mob_at_worker_adv_rec") or "0"
        )
        txn_type = "Expense"

    if date_err := _at_entry_date_error():
        st.error(date_err)
        _at_set_flash("error", date_err)
    elif pm_err := _at_validate_payment_method_for_submit(session, txn_type):
        st.error(pm_err)
        _at_set_flash("error", pm_err)
    elif not amount or amount <= 0:
        _msg = _t("txn.invalid_amount_zero")
        st.error(_msg)
        _at_set_flash("error", _msg)
    elif txn_type == "Sale" and ctx["at_payment_method"] == "Credit" and (
        _cr_cust_err := _at_sale_credit_customer_error(ctx.get("customer_name_val"))
    ):
        st.error(_cr_cust_err)
        _at_set_flash("error", _cr_cust_err)
    elif _mob_at_is_salary_mode() and not st.session_state.get("at_worker_id"):
        st.error(_t("txn.expense_worker_required"))
    elif _mob_at_is_salary_mode() and not _parse_amount_str(
        st.session_state.get("mob_at_worker_gross", "")
    ):
        st.error(_t("txn.invalid_amount_zero"))
    elif txn_type == "Supplier Payment" and (
        sp_err := _at_supplier_payment_submit_error(
            session,
            vendors,
            ctx.get("vendor_name_val"),
            st.session_state.get("at_payable_id"),
        )
    ):
        st.error(sp_err)
        _at_set_flash("error", sp_err)
    elif txn_type == "Supplier Payment" and st.session_state.get("at_payable_id"):
        payable = session.get(Payable, st.session_state["at_payable_id"])
        if payable and (
            pay_err := _validate_payable_payment_amount(
                payable, amount, currency=currency_default
            )
        ):
            st.error(pay_err)
            _at_set_flash("error", pay_err)
    elif txn_type == "Customer Payment" and not open_sales:
        st.error(_t("txn.no_credit_invoices"))
    elif txn_type == "Customer Payment" and open_sales and not ctx.get("invoice_choice_val"):
        _inv_err = _t("txn.invoice_not_selected")
        st.error(_inv_err)
        _at_set_flash("error", _inv_err)
    elif (
        ctx["at_payment_method"] == "Bank"
        and bank_accounts
        and not st.session_state.get("at_bank_pay_acct")
    ):
        st.error(_t("txn.bank_not_selected"))
    elif (
        _cc_card_err := _validate_company_cc_card(
            session, ctx["at_payment_method"], _submit_cc_card_id
        )
    ):
        st.error(_cc_card_err)
        _at_set_flash("error", _cc_card_err)
    else:
        _at_dev_log_submit("pre_save", txn_type=txn_type, ctx=ctx, amount=amount, reached_save=True)
        try:
            _selected_currency = st.session_state.get("at_currency", currency_default)
            st.session_state["_at_save_succeeded"] = False
            _at_save(
                session=session,
                txn_type=txn_type,
                date=ctx["date"],
                amount=amount,
                currency=_selected_currency,
                payment_method=ctx["at_payment_method"],
                notes=ctx["at_notes"],
                customer_name=ctx["customer_name_val"],
                category=ctx["effective_category"],
                vendor_name=ctx["vendor_name_val"],
                invoice_choices=ctx["invoice_choices"],
                invoice_choice_val=ctx["invoice_choice_val"],
                open_sales=open_sales,
                bank_sub=ctx["bank_sub"],
                bank_acct_val=ctx["bank_acct_val"],
                bank_dest_val=ctx["bank_dest_val"],
                bank_accounts=bank_accounts,
                vendors=vendors,
                tx_category_id=ctx["at_cat_id"],
                tx_subcategory_id=at_subcat_id,
                subcats_list=ctx["subcats_list"],
                at_subcat_name=ctx["at_subcat_name"],
                fx_rate=ctx["at_fx_rate"],
                card_bank_acct_val=st.session_state.get("at_card_bank_acct"),
                bank_payment_acct_val=st.session_state.get("at_bank_pay_acct"),
                selected_payable_id=st.session_state.get("at_payable_id"),
                credit_card_account_id=_submit_cc_card_id,
            )
            if st.session_state.pop("_at_save_succeeded", False):
                _at_clear_post_save_transient_fields()
                _at_refresh_date_text_display()
                st.rerun()
        except Exception as exc:
            st.error(_t("txn.save_failed", error=exc))


def _mob_at_button_row(
    options: list[tuple[str, str]],
    active: str,
    key_prefix: str,
    state_key: str,
    *,
    row_key: str,
) -> bool:
    """Horizontal chip row inside a keyed container (CSS grid on mobile)."""
    if not options:
        return False
    with st.container(border=False, key=row_key):
        cols = st.columns(len(options), gap="small")
        for col, (val, label) in zip(cols, options):
            if col.button(
                label,
                key=f"{key_prefix}_{val}",
                use_container_width=True,
                type="primary" if active == val else "secondary",
            ):
                st.session_state[state_key] = val
                _at_clear_stale_payment_account_keys(val)
                return True
    return False


def _render_add_transaction_mobile(
    session,
    *,
    currency_default: str,
    vendors: list,
    bank_accounts: list,
    open_sales: list,
    type_names: list[str],
    type_display_map: dict,
) -> bool:
    """Mobile entry screen: today summary + fixed bottom panel. Returns True if save clicked."""
    _mob_at_apply_date_follow_today()
    today = datetime.date.today()
    if "mob_at_tab" not in st.session_state:
        idx = st.session_state.get("at_type_idx", 0)
        st.session_state["mob_at_tab"] = idx if idx <= 2 else 3
        if idx > 2:
            st.session_state["mob_at_more_idx"] = idx
    if "mob_at_more_idx" not in st.session_state:
        st.session_state["mob_at_more_idx"] = 3

    _mob_at_sync_type_from_tab()
    txn_type = _at_effective_txn_type(type_names)
    _mob_at_ensure_defaults(session, txn_type, currency_default, vendors)

    with st.container(border=False, key="mob_at_topbar"):
        bc, tc = st.columns([1, 3], gap="small")
        with bc:
            if st.button(
                f"← {_tf('txn.mob.back', 'Home')}",
                key="mob_at_back_home",
                use_container_width=True,
            ):
                st.session_state["nav_selection"] = NAV_HOME
                st.rerun()
        with tc:
            st.markdown(
                mobile_screen_title_html(_tf("txn.mob.title", "New transaction")),
                unsafe_allow_html=True,
            )

    today_sales, today_expenses, today_net = _mob_at_today_metrics(session, today)
    _fmt = lambda v: f"{currency_default} {v:,.2f}"
    _net_variant = "success" if today_net >= 0 else "danger"

    st.markdown(
        mobile_kpi_grid_html(
            mobile_kpi_chip_html(_tf("txn.mob.kpi.sales", "Sales"), _fmt(today_sales), variant="success"),
            mobile_kpi_chip_html(_tf("txn.mob.kpi.expenses", "Expenses"), _fmt(today_expenses), variant="danger"),
            mobile_kpi_chip_html(_tf("txn.mob.kpi.net", "Net"), _fmt(today_net), variant=_net_variant),
        ),
        unsafe_allow_html=True,
    )

    st.markdown(
        mobile_section_label_html(_tf("txn.mob.today", "Today")),
        unsafe_allow_html=True,
    )
    rows = _mob_at_today_rows(session, today)
    if rows:
        _rows_html = ""
        for r in rows:
            sign = "+" if r["direction"] == "in" else "−"
            amt_variant = "in" if r["direction"] == "in" else "out"
            icon_bg = (
                "color-mix(in srgb,var(--theme-success)12%,var(--theme-card)88%)"
                if r["direction"] == "in"
                else "color-mix(in srgb,var(--theme-danger)12%,var(--theme-card)88%)"
            )
            _rows_html += mobile_list_row_html(
                str(r["party"]),
                subtitle=r["sub"],
                amount=f'{sign}{currency_default} {r["amount"]:,.2f}',
                amount_variant=amt_variant,
                icon_block=(
                    f'<div class="erp-mob-at-row-icon" style="background:{icon_bg};">'
                    f'{r["icon"]}</div>'
                ),
            )
        st.markdown(_rows_html, unsafe_allow_html=True)
    else:
        st.markdown(
            mobile_empty_state_html(_tf("txn.mob.no_today", "No transactions today yet")),
            unsafe_allow_html=True,
        )

    _pending_att = st.session_state.get("at_pending_attachment")
    if _pending_att:
        st.caption(_t("txn.pending_attachment_hint", filename=_pending_att.get("name", "")))

    with st.container(border=False, key="erp_mob_at_panel"):
        _picker = st.session_state.get("mob_at_picker")
        if _picker:
            st.markdown(
                '<div class="erp-at-picker-open-host"></div>',
                unsafe_allow_html=True,
            )
            if _mob_at_render_picker_sheet(
                session,
                picker_kind=_picker,
                vendors=vendors,
                open_sales=open_sales,
                bank_accounts=bank_accounts,
                currency_default=currency_default,
            ):
                st.rerun()
        else:
            st.markdown(
                '<div class="erp-mob-at-panel-top"><div class="erp-mob-at-panel-caret"></div></div>',
                unsafe_allow_html=True,
            )

            # ── Concept C: Row 1 (type | date | currency) + PM chip row (UX-04B) ──
            _mob_at_render_c_row1(currency_default)

            # Re-derive type after any picker selection in this render pass
            at_idx = st.session_state.get("at_type_idx", 0)
            if _mob_at_is_salary_mode():
                at_idx = _MOB_AT_SALARY_IDX
            txn_type = (
                type_names[at_idx]
                if 0 <= at_idx < len(type_names)
                else "Expense"
            )
            _mob_at_ensure_defaults(session, txn_type, currency_default, vendors)

            if _mob_at_render_pm_chip_row(session, txn_type):
                st.rerun()

            # ── Context-specific fields ──
            if _mob_at_is_salary_mode():
                workers = (
                    cq(session, Worker)
                    .filter_by(is_active=True)
                    .order_by(Worker.name)
                    .all()
                )
                if workers:
                    w_labels = {w.id: w.name for w in workers}
                    st.selectbox(
                        _t("worker.mv_worker_label"),
                        options=list(w_labels.keys()),
                        format_func=lambda i: w_labels[i],
                        key="mob_at_worker_id",
                        label_visibility="collapsed",
                    )
                else:
                    st.caption(_t("worker.no_workers"))
                if _mob_at_maybe_bank_pay_trigger(bank_accounts, payment_method=st.session_state.get("at_pm", "Cash")):
                    st.rerun()
                _mob_at_render_salary_fields(session, currency_default)
                _mob_at_render_fx_hook(currency_default)

            elif at_idx == 0:  # Sale
                if st.session_state.get("at_pm") == "Card" and not _card_settlement_on(session):
                    _at_clear_invalid_card_bank_selection(bank_accounts)
                    _deposit_accts = _at_sale_card_deposit_accounts(bank_accounts)
                    if _deposit_accts:
                        if _mob_at_render_card_bank_trigger(bank_accounts):
                            st.rerun()
                    else:
                        st.caption(_t("txn.no_bank_add"))
                _mob_at_render_fx_hook(currency_default)

            elif at_idx == 1:  # Expense
                if _mob_at_render_quick_cat_chips(session, "Expense", picker_kind="expense_cat"):
                    st.rerun()
                if _mob_at_render_subcategory_trigger(session, "Expense", picker_kind="expense_subcat"):
                    st.rerun()
                if _mob_at_maybe_bank_pay_trigger(bank_accounts, payment_method=st.session_state.get("at_pm", "Cash")):
                    st.rerun()
                _mob_at_render_company_cc_select(session, txn_type="Expense")
                _mob_at_render_fx_hook(currency_default)

            elif at_idx == 2:  # Purchase
                if _mob_at_render_vendor_trigger(session, vendors):
                    st.rerun()
                if _mob_at_render_quick_cat_chips(session, "Purchase", picker_kind="purchase_cat"):
                    st.rerun()
                if _mob_at_render_subcategory_trigger(session, "Purchase", picker_kind="purchase_subcat"):
                    st.rerun()
                if _mob_at_maybe_bank_pay_trigger(bank_accounts, payment_method=st.session_state.get("at_pm", "Cash")):
                    st.rerun()
                _mob_at_render_company_cc_select(session, txn_type="Purchase")
                _mob_at_render_fx_hook(currency_default)

            elif txn_type == "Customer Payment":
                if open_sales:
                    if _mob_at_render_invoice_trigger(open_sales):
                        st.rerun()
                    _mob_inv = _at_sale_from_invoice_choice(
                        open_sales, st.session_state.get("at_inv")
                    )
                    if _mob_inv:
                        st.caption(
                            _t(
                                "txn.payable_outstanding",
                                currency=currency_default,
                                balance=_mob_inv.balance,
                            )
                        )
                if _mob_at_maybe_bank_pay_trigger(bank_accounts, payment_method=st.session_state.get("at_pm", "Cash")):
                    st.rerun()
                _mob_at_render_fx_hook(currency_default)

            elif txn_type == "Supplier Payment":
                _at_clear_category_session_state()
                if _mob_at_render_vendor_trigger(session, vendors):
                    st.rerun()
                if vendors and st.session_state.get("at_vendor"):
                    _mob_at_sync_select_widgets()
                    _sp_vendor = next(
                        (v for v in vendors if v.name == st.session_state.get("at_vendor")),
                        None,
                    )
                    _pay_opts = (
                        _mob_at_payable_options(session, _sp_vendor.id, currency_default)
                        if _sp_vendor
                        else []
                    )
                    if _pay_opts:
                        if _mob_at_render_payable_trigger(session, vendors, currency_default):
                            st.rerun()
                        if st.session_state.get("at_payable_id"):
                            _mob_pay = session.get(Payable, st.session_state["at_payable_id"])
                            if _mob_pay:
                                st.caption(
                                    _t(
                                        "txn.payable_outstanding",
                                        currency=currency_default,
                                        balance=_payable_balance(_mob_pay),
                                    )
                                )
                    else:
                        st.caption(_t("txn.no_open_payable"))
                if _mob_at_maybe_bank_pay_trigger(bank_accounts, payment_method=st.session_state.get("at_pm", "Cash")):
                    st.rerun()
                _mob_at_render_company_cc_select(session, txn_type="Supplier Payment")
                _mob_at_render_fx_hook(currency_default)

            elif txn_type == "Bank Transaction" and bank_accounts:
                if _mob_at_render_bank_trigger(bank_accounts):
                    st.rerun()
                if _mob_at_button_row(
                    [("Deposit", "Deposit"), ("Withdrawal", "Withdrawal")],
                    st.session_state.get("at_bank_sub", "Deposit"),
                    "mob_at_bank",
                    "at_bank_sub",
                    row_key="mob_at_pm2",
                ):
                    st.rerun()

            _mob_at_render_amount_keypad_fragment(currency_default)

    _mob_at_sync_select_widgets()
    return False


def render_add_transaction(session):
    """Modern Add Transaction page with professional two-column layout."""
    settings        = load_settings()
    currency_default = settings.get("currency", "TRY")

    # ── Data queries ──────────────────────────────────────────────────────────
    vendors = cq(session, Vendor).filter_by(is_active=True).order_by(Vendor.name).all()
    bank_accounts = cq(session, BankAccount).filter_by(is_active=True).order_by(BankAccount.name).all()
    open_sales = (
        cq(session, Sale)
        .filter(Sale.sale_type == "Credit", Sale.is_void == False, Sale.balance > 0)
        .order_by(Sale.date.desc()).all()
    )

    # ── Type metadata with modern colors ───────────────────────────────────────
    _TYPES = [
        ("Sale",             "🧾", "#16A34A", "#dcfce7", "#86efac"),
        ("Expense",          "💳", "#EF4444", "#fee2e2", "#fca5a5"),
        ("Purchase",         "🛒", "#8B5CF6", "#f3e8ff", "#d8b4fe"),
        ("Supplier Payment", "🏢", "#F59E0B", "#fef3c7", "#fde68a"),
        ("Customer Payment", "💰", "#3B82F6", "#eff6ff", "#bfdbfe"),
        ("Bank Transaction", "🏦", "#14B8A6", "#f0fdfa", "#99f6e4"),
    ]
    _TYPE_NAMES = [t[0] for t in _TYPES]
    _TYPE_MAP   = {t[0]: t[1:] for t in _TYPES}  # name → (icon, color, bg, border)
    _TYPE_KEY_MAP = {
        "Sale": "txn.type_short.sale", "Expense": "txn.type_short.expense",
        "Purchase": "txn.type_short.purchase", "Supplier Payment": "txn.type_short.supplier_payment",
        "Customer Payment": "txn.type_short.customer_payment", "Bank Transaction": "txn.type_short.bank_transaction",
    }
    _TYPE_CSS_CLASS = {
        "Sale": "sale",
        "Expense": "expense",
        "Purchase": "purchase",
        "Supplier Payment": "supplier",
        "Customer Payment": "customer",
        "Bank Transaction": "bank",
    }
    _TYPE_DISPLAY_MAP = {
        "Sale": "txn.type.sale", "Expense": "txn.type.expense",
        "Purchase": "txn.type.purchase", "Supplier Payment": "txn.type.supplier_payment",
        "Customer Payment": "txn.type.customer_payment", "Bank Transaction": "txn.type.bank_transaction",
    }
    _TIP_KEY_MAP = {
        "Sale": "txn.tip.sale", "Expense": "txn.tip.expense", "Purchase": "txn.tip.purchase",
        "Supplier Payment": "txn.tip.supplier_payment", "Customer Payment": "txn.tip.customer_payment",
        "Bank Transaction": "txn.tip.bank_transaction",
    }

    # ── Session state ─────────────────────────────────────────────────────────
    _cache_user_date_format(session)
    _is_mobile_at = _sync_mobile_ui_flag_from_cookie()
    if "at_type_idx" not in st.session_state:
        st.session_state["at_type_idx"] = 0
    if "at_amount_display" not in st.session_state:
        st.session_state["at_amount_display"] = ""
    if not _is_mobile_at:
        _at_sync_desktop_type_to_mobile_tabs()

    txn_type              = _at_effective_txn_type(_TYPE_NAMES)
    type_icon, type_color, type_bg, type_border = _TYPE_MAP[txn_type]
    _type_css             = _TYPE_CSS_CLASS.get(txn_type, "sale")
    _coerce_at_payment_method(session, txn_type)
    _mob_at_ensure_defaults(session, txn_type, currency_default, vendors)

    # ── Category / Subcategory lookup (must stay outside layout for live rerender)
    at_cat       = None
    at_cat_id    = None
    subcats_list = []
    cats         = []
    if txn_type in ("Expense", "Purchase"):
        cats = _at_filter_transaction_categories(
            cq(session, TransactionCategory)
            .filter_by(transaction_type=txn_type, is_active=True)
            .order_by(TransactionCategory.name)
            .all()
        )
    elif txn_type == "Supplier Payment":
        _at_clear_category_session_state()

    _at_render_flash()

    mob_submitted = False
    if _is_mobile_at:
        with st.container(key="erp_at_mobile_screen"):
            st.markdown('<div class="erp-at-mobile-host"></div>', unsafe_allow_html=True)
            mob_submitted = _render_add_transaction_mobile(
                session,
                currency_default=currency_default,
                vendors=vendors,
                bank_accounts=bank_accounts,
                open_sales=open_sales,
                type_names=_TYPE_NAMES,
                type_display_map=_TYPE_DISPLAY_MAP,
            )
    else:
        _at_clear_stale_mobile_overlay_state()

    submitted = False
    if not _is_mobile_at:
        with st.container(key="erp_at_desktop_host"):
            # ── Page header (same pattern as Sales / Expenses — not deferred to 16C) ─
            _st_page_title(i18n_key="txn.add_title")
            st.caption(_t("txn.add_caption"))
            _pending_att = st.session_state.get("at_pending_attachment")
            if _pending_att:
                st.info(_t("txn.pending_attachment_hint", filename=_pending_att.get("name", "")))
            _type_label = _t(_TYPE_DISPLAY_MAP.get(txn_type, "txn.type.sale"))
            st.markdown(
                f'<div style="margin:8px 0 16px;">'
                f'<span class="txn-type-badge {_type_css}">{type_icon} {_type_label}</span>'
                f'</div>',
                unsafe_allow_html=True,
            )

            # ══════════════════════════════════════════════════════════════════════════
            # TWO-COLUMN LAYOUT (35% left, 65% right)
            # ══════════════════════════════════════════════════════════════════════════
            left_col, right_col = st.columns([35, 65], gap="large")

            # ════════════ LEFT PANEL (35%) ════════════
            with left_col:

                # ── AMOUNT CARD ────────────────────────────────────────────────────────
                with st.container(border=True):
                    st.markdown(
                        f'<div style="font-size:11px;font-weight:700;color:var(--theme-muted);'
                        f'text-transform:uppercase;letter-spacing:.08em;margin-bottom:12px;'
                        f'display:flex;align-items:center;justify-content:space-between;">'
                        f'<span>{_t("txn.amount_label")}</span>'
                        f'<span style="background:var(--theme-info);color:#fff;'
                        f'padding:2px 8px;border-radius:4px;font-size:9px;font-weight:700;">{currency_default}</span>'
                        f'</div>',
                        unsafe_allow_html=True,
                    )
                    amount_raw = st.text_input(
                        "Amount",
                        placeholder="0.00",
                        key="at_amount_display",
                        label_visibility="collapsed",
                    )
                    if txn_type == "Supplier Payment" and st.session_state.get("at_payable_id"):
                        _sp_pay = session.get(Payable, st.session_state["at_payable_id"])
                        if _sp_pay:
                            _sp_bal = _payable_balance(_sp_pay)
                            st.caption(
                                _t(
                                    "txn.payable_outstanding",
                                    currency=currency_default,
                                    balance=_sp_bal,
                                )
                            )
    
                # ── TRANSACTION TYPE CARDS ─────────────────────────────────────────────
                st.markdown(
                    '<div style="font-size:11px;font-weight:700;color:var(--theme-muted);'
                    f'text-transform:uppercase;letter-spacing:.08em;margin:16px 0 10px;">{_t("txn.transaction_type_header")}</div>',
                    unsafe_allow_html=True,
                )
                tc1, tc2 = st.columns(2, gap="small")
                for _i, (_tname, _ticon, _tcolor, _tbg, _tborder) in enumerate(_TYPES):
                    _is_active = st.session_state["at_type_idx"] == _i
                    _short     = _t(_TYPE_KEY_MAP.get(_tname, "txn.type_short.sale"))
                    _col       = tc1 if _i % 2 == 0 else tc2
                    if _col.button(
                        f"{_ticon}\n{_short}",
                        key=f"at_type_{_i}",
                        use_container_width=True,
                        type="primary" if _is_active else "secondary",
                    ):
                        if st.session_state["at_type_idx"] != _i:
                            _at_clear_category_session_state()
                        st.session_state["at_type_idx"] = _i
                        _coerce_at_payment_method(session, _tname)
                        _at_sync_desktop_type_to_mobile_tabs()
                        st.rerun()
    
                # ── TIP BOX (type-specific) ────────────────────────────────────────────
                _tip_text = _t(_TIP_KEY_MAP.get(txn_type, "txn.tip.default"))
                st.markdown(
                    f'<div class="txn-tip-box {_type_css}">'
                    f'<div class="txn-tip-title">{_t("txn.pro_tip")}</div>'
                    f'<div style="color:var(--theme-muted);">{_tip_text}</div>'
                    f'</div>',
                    unsafe_allow_html=True,
                )

            # ════════════ RIGHT PANEL (65%) ════════════
            with right_col:
                with st.container(border=True):
                    # ── Pre-init all branch variables ─────────────────────────────────
                    customer_name_val = ""
                    vendor_name_val   = None
                    at_payment_method = "Cash"
                    invoice_choice_val = None
                    invoice_choices: list = []
                    bank_sub      = "Deposit"
                    bank_acct_val = bank_accounts[0].name if bank_accounts else None
                    bank_dest_val = None
                    at_subcat_name = None

                    st.markdown(
                        f'<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;'
                        f'padding-bottom:12px;border-bottom:2px solid var(--theme-border);">'
                        f'<div class="txn-details-icon {_type_css}">{type_icon}</div>'
                        f'<div>'
                        f'<div style="font-size:16px;font-weight:800;color:var(--theme-text);">'
                        f'{_t("txn.details_header", type=_type_label)}</div>'
                        f'<div style="font-size:12px;color:var(--theme-muted);margin-top:4px;">'
                        f'{_t("txn.fill_details")}</div>'
                        f'</div>'
                        f'</div>',
                        unsafe_allow_html=True,
                    )

                    with st.form("at_entry_form", clear_on_submit=False):
                        # ADD-TXN-FIX date UX — single Date field INSIDE the form so
                        # Enter submits; calendar helper is a collapsed expander
                        # (callback-free; reconciled in _at_resolve_entry_date).
                        _at_render_desktop_date_field()
                        # ── CONDITIONAL FIELDS BY TRANSACTION TYPE ─────────────────────
                        if txn_type == "Sale":
                            fc1, fc2 = st.columns(2)
                            at_payment_method = fc1.selectbox(
                                "💳 " + _t("form.payment_method"), ["Cash", "Card", "Credit"],
                                format_func=lambda v: _at_payment_method_label("Sale", v),
                                key="at_pm",
                            )
                            fc2.selectbox(
                                "💱 " + _t("txn.currency_label"), CURRENCIES,
                                index=CURRENCIES.index(currency_default) if currency_default in CURRENCIES else 0,
                                key="at_currency",
                            )
                            if at_payment_method == "Card" and not _card_settlement_on(session):
                                _at_clear_invalid_card_bank_selection(bank_accounts)
                                _card_acct_names = [
                                    a.name for a in _at_sale_card_deposit_accounts(bank_accounts)
                                ]
                                if _card_acct_names:
                                    st.selectbox(
                                        "🏦 " + _t("txn.bank_account_label"),
                                        _card_acct_names,
                                        key="at_card_bank_acct",
                                        help=_t("txn.card_settle_help"),
                                    )
                                else:
                                    st.info(_t("txn.no_bank_add"))
                            if at_payment_method == "Credit":
                                _customers = cq(session, Customer).filter_by(is_active=True).order_by(Customer.name).all()
                                if _customers:
                                    _cust_options = ["— type manually —"] + [c.name for c in _customers]
                                    _cust_sel = st.selectbox("👤 " + _t("txn.customer_dd_label"), _cust_options, key="at_cust_sel")
                                    if _cust_sel == "— type manually —":
                                        customer_name_val = st.text_input(_t("txn.customer_name"), placeholder=_t("txn.customer_name_ph"), key="at_cust")
                                    else:
                                        customer_name_val = _cust_sel
                                        st.session_state["at_cust"] = _cust_sel
                                else:
                                    customer_name_val = st.text_input(
                                        "👤 " + _t("txn.customer_name"), placeholder=_t("txn.customer_name_ph"), key="at_cust"
                                    )

                        elif txn_type == "Expense":
                            fc1, fc2 = st.columns(2)
                            at_payment_method = fc1.selectbox(
                                "💳 " + _t("form.payment_method"),
                                _at_expense_pay_methods(session),
                                format_func=lambda v: _at_payment_method_label("Expense", v),
                                key="at_pm",
                            )
                            fc2.selectbox("💱 " + _t("txn.currency_label"), CURRENCIES,
                                          index=CURRENCIES.index(currency_default) if currency_default in CURRENCIES else 0,
                                          key="at_currency")

                            _exp_modes = ["general", "worker"]
                            if not _has_active_workers(session):
                                _exp_modes = ["general"]
                            expense_mode = st.radio(
                                _t("txn.expense_mode_label"),
                                _exp_modes,
                                format_func=lambda m: _t(f"txn.expense_mode.{m}"),
                                horizontal=True,
                                key="at_expense_mode",
                            )

                            if expense_mode == "worker":
                                st.caption(_t("txn.expense_mode.worker_hint"))
                                workers = (
                                    cq(session, Worker)
                                    .filter_by(is_active=True)
                                    .order_by(Worker.name)
                                    .all()
                                )
                                w_labels = {w.id: w.name for w in workers}
                                st.selectbox(
                                    _t("worker.mv_worker_label"),
                                    options=list(w_labels.keys()),
                                    format_func=lambda i: w_labels[i],
                                    key="at_worker_id",
                                )
                                st.selectbox(
                                    _t("worker.mv_type_label"),
                                    ["Salary", "Advance"],
                                    format_func=lambda v: _i18n_db(_WORKER_MOVEMENT_TYPE_I18N, v),
                                    key="at_worker_mv_type",
                                )
                                if st.session_state.get("at_worker_mv_type") == "Salary":
                                    st.text_input(_t("worker.pay_period"), key="at_worker_period")
                                    sc1, sc2 = st.columns(2)
                                    amount_input(
                                        _t("worker.gross"),
                                        key="at_worker_gross",
                                        container=sc1,
                                    )
                                    amount_input(
                                        _t("worker.deductions"),
                                        key="at_worker_ded",
                                        default=0.0,
                                        container=sc2,
                                    )
                                    amount_input(
                                        _t("worker.advance_recovery"),
                                        key="at_worker_adv_rec",
                                        default=0.0,
                                    )
                                    _wid = st.session_state.get("at_worker_id")
                                    if _wid:
                                        _adv = get_worker_advance_balance(session, _wid)
                                        if _adv > 0.01:
                                            st.caption(
                                                _t(
                                                    "worker.advance_max_hint",
                                                    currency=currency_default,
                                                    amount=_adv,
                                                )
                                            )
                                    st.caption(_t("txn.expense_worker_net_hint"))
                                else:
                                    st.caption(_t("txn.expense_worker_advance_hint"))
                                at_cat = at_cat_id = None
                                at_subcat_name = None
                                subcats_list = []
                            else:
                                at_cat, at_cat_id = _inline_cat_row(
                                    session, txn_type, cats, inside_form=True
                                )
                                at_subcat_name, subcats_list = _inline_subcat_row(
                                    session, at_cat, inside_form=True
                                )
                            _at_render_bank_pay_select(bank_accounts)
                            _at_render_company_cc_select(session, txn_type="Expense")

                        elif txn_type == "Purchase":
                            vendor_name_val = _inline_vendor_row(
                                session, vendors, inside_form=True
                            )
                            fc1, fc2 = st.columns(2)
                            at_payment_method = fc1.selectbox(
                                "💳 " + _t("form.payment_method"),
                                _at_purchase_pay_methods(session),
                                format_func=lambda v: _at_payment_method_label("Purchase", v),
                                key="at_pm",
                            )
                            fc2.selectbox("💱 " + _t("txn.currency_label"), CURRENCIES,
                                          index=CURRENCIES.index(currency_default) if currency_default in CURRENCIES else 0,
                                          key="at_currency")

                            at_cat, at_cat_id = _inline_cat_row(
                                session, txn_type, cats, inside_form=True
                            )
                            at_subcat_name, subcats_list = _inline_subcat_row(
                                session, at_cat, inside_form=True
                            )
                            _at_render_bank_pay_select(bank_accounts)
                            _at_render_company_cc_select(session, txn_type="Purchase")

                        elif txn_type == "Supplier Payment":
                            _at_clear_category_session_state()
                            vendor_name_val = _inline_vendor_row(
                                session, vendors, inside_form=True
                            )

                            # ── Open payable selector ─────────────────────────────────
                            if vendors and vendor_name_val:
                                _sp_vendor = next((v for v in vendors if v.name == vendor_name_val), None)
                                if _sp_vendor:
                                    # Reset selection when vendor changes
                                    if st.session_state.get("at_last_vendor") != vendor_name_val:
                                        st.session_state.pop("at_payable_id", None)
                                        st.session_state["at_last_vendor"] = vendor_name_val

                                    _open_pays = (
                                        cq(session, Payable)
                                        .filter_by(vendor_id=_sp_vendor.id, paid=False, is_void=False)
                                        .order_by(Payable.date)
                                        .all()
                                    )
                                    if _open_pays:
                                        _pay_ph = _t("txn.select_payable_ph")
                                        _pay_labels = []
                                        for _p in _open_pays:
                                            _pbal = _payable_balance(_p)
                                            _pref = f"PUR#{_p.purchase_id}" if _p.purchase_id else f"PAY#{_p.id}"
                                            _pay_labels.append(
                                                f"{_p.date.strftime('%d %b %Y')} · {_pref} · "
                                                f"Balance: {currency_default} {_pbal:,.2f}"
                                            )
                                        _pay_options = [_pay_ph] + _pay_labels
                                        _cur_pid = st.session_state.get("at_payable_id")
                                        _cur_idx = 0
                                        if _cur_pid:
                                            _cur_idx = next(
                                                (
                                                    i + 1
                                                    for i, p in enumerate(_open_pays)
                                                    if p.id == _cur_pid
                                                ),
                                                0,
                                            )
                                        _sel_label = st.selectbox(
                                            "📌 Invoice / Payable to Settle",
                                            _pay_options,
                                            index=_cur_idx,
                                            key="at_payable_sel",
                                        )
                                        if _sel_label == _pay_ph:
                                            st.session_state.pop("at_payable_id", None)
                                        else:
                                            _sel_p = _open_pays[_pay_labels.index(_sel_label)]
                                            st.session_state["at_payable_id"] = _sel_p.id
                                            _pbal = _payable_balance(_sel_p)
                                            _pdesc = (_sel_p.description or "")[:50]
                                            st.markdown(
                                                f'<div class="card" style="padding:9px 14px;margin-top:4px;font-size:11px;">'
                                                f'Original: <b>{currency_default} {_sel_p.amount:,.2f}</b>'
                                                f'&nbsp;·&nbsp;Paid: <b>{currency_default} {_sel_p.paid_amount or 0:,.2f}</b>'
                                                f'&nbsp;·&nbsp;Balance: <span style="font-weight:700;color:var(--theme-warning-text);">'
                                                f'{currency_default} {_pbal:,.2f}</span>'
                                                f'{"<br><span style=\'color:var(--theme-muted);\'>" + _pdesc + "</span>" if _pdesc else ""}'
                                                f'</div>',
                                                unsafe_allow_html=True,
                                            )
                                    else:
                                        st.warning(_t("txn.no_open_payables", name=vendor_name_val))
                                        st.session_state["at_payable_id"] = None

                            fc1, fc2 = st.columns(2)
                            at_payment_method = fc1.selectbox(
                                "💳 " + _t("form.payment_method"),
                                _at_supplier_pay_methods(session),
                                format_func=lambda v: _at_payment_method_label("Supplier Payment", v),
                                key="at_pm",
                            )
                            fc2.selectbox(
                                "💱 " + _t("txn.currency_label"),
                                CURRENCIES,
                                index=CURRENCIES.index(currency_default) if currency_default in CURRENCIES else 0,
                                key="at_currency",
                            )
                            _at_render_bank_pay_select(bank_accounts)
                            _at_render_company_cc_select(session, txn_type="Supplier Payment")

                        elif txn_type == "Customer Payment":
                            if open_sales:
                                invoice_choices = [_at_invoice_choice_label(s) for s in open_sales]
                                _inv_ph = _t("txn.select_invoice_ph")
                                _inv_options = [_inv_ph] + invoice_choices
                                _cur_inv = st.session_state.get("at_inv")
                                _inv_idx = 0
                                if _cur_inv in invoice_choices:
                                    _inv_idx = invoice_choices.index(_cur_inv) + 1
                                fc1, fc2, fc3 = st.columns(3)
                                _inv_sel = fc1.selectbox(
                                    "📄 " + _t("txn.open_invoice_label"),
                                    _inv_options,
                                    index=_inv_idx,
                                    key="at_inv",
                                )
                                if _inv_sel == _inv_ph:
                                    invoice_choice_val = None
                                    st.session_state.pop("at_inv", None)
                                else:
                                    invoice_choice_val = _inv_sel
                                    _sel_sale = _at_sale_from_invoice_choice(
                                        open_sales, invoice_choice_val
                                    )
                                    if _sel_sale:
                                        st.caption(
                                            _t(
                                                "txn.payable_outstanding",
                                                currency=currency_default,
                                                balance=_sel_sale.balance,
                                            )
                                        )
                                at_payment_method  = fc2.selectbox(
                                    "💳 " + _t("form.payment_method"),
                                    ["Cash", "Bank"],
                                    format_func=lambda v: _at_payment_method_label("Customer Payment", v),
                                    key="at_pm",
                                )
                                fc3.selectbox("💱 " + _t("txn.currency_label"), CURRENCIES,
                                              index=CURRENCIES.index(currency_default) if currency_default in CURRENCIES else 0,
                                              key="at_currency")
                                _at_render_bank_pay_select(bank_accounts)
                            else:
                                st.info(_t("txn.no_credit_invoices"))

                        elif txn_type == "Bank Transaction":
                            # Step 3.2: currency auto-locks to the selected bank account's currency
                            fc1, fc2 = st.columns(2)
                            bank_sub = fc1.selectbox(_t("col.type"), ["Deposit", "Withdrawal", "Transfer"], key="at_bank_sub")
                            if bank_accounts:
                                acct_names    = [a.name for a in bank_accounts]
                                bank_acct_val = fc2.selectbox("🏦 " + _t("txn.bank_account_label"), acct_names, key="at_bank_acct")
                                # Detect currency from selected account name (e.g. "Bank USD" → USD)
                                _auto_ccy = next(
                                    (c for c in CURRENCIES if bank_acct_val and bank_acct_val.endswith(f" {c}")),
                                    currency_default,
                                )
                                st.session_state["at_currency"] = _auto_ccy
                                st.caption(_t("txn.currency_locked", currency=_auto_ccy))
                                if bank_sub == "Transfer":
                                    bd1, _bd2 = st.columns(2)
                                    bank_dest_val = bd1.selectbox(
                                        _t("txn.destination_account"), acct_names, key="at_bank_dest"
                                    )
                            else:
                                fc1.warning(_t("txn.no_bank_accounts_hint"))

                        # ── FX RATE (shown only when transaction currency differs from reporting) ──
                        _sel_ccy = st.session_state.get("at_currency", currency_default)
                        at_fx_rate = 1.0
                        if _sel_ccy and _sel_ccy != currency_default:
                            _fx_raw = amount_input(
                                f"💱 FX Rate ({currency_default} per {_sel_ccy})",
                                key="at_fx_rate",
                                placeholder=_t("txn.fx_placeholder"),
                                default=st.session_state.get("at_fx_rate_val"),
                            )
                            at_fx_rate = _fx_raw if _fx_raw and _fx_raw > 0 else 1.0
                            st.session_state["at_fx_rate_val"] = at_fx_rate
                            st.caption(_t("txn.native_amount", currency=currency_default, amount=((_parse_amount_str(amount_raw) or 0) * at_fx_rate)))

                        # ── NOTES FIELD (Full width) ──────────────────────────────────────
                        st.text_area(
                            _t("txn.notes_description"),
                            placeholder=_t("txn.notes_placeholder"),
                            key="at_notes_field",
                            height=90,
                        )

                        # ── SAVE SECTION ──────────────────────────────────────────────────
                        st.markdown("<div style='margin-top:16px;'></div>", unsafe_allow_html=True)
                        st.markdown(
                            f'<p style="margin:0 0 8px;font-size:12px;color:var(--theme-muted);">'
                            f'{html.escape(_t("txn.enter_to_save_hint"))}</p>',
                            unsafe_allow_html=True,
                        )
                        submitted = st.form_submit_button(
                            _t("txn.save_btn", type=_t(_TYPE_DISPLAY_MAP.get(txn_type, txn_type))),
                            type="primary",
                            use_container_width=True,
                            help=_t("txn.save_help"),
                        )
                        if submitted:
                            _at_capture_submit_resolved_date()

    else:
        with st.container(key="erp_at_desktop_host"):
            st.markdown('<div class="erp-at-desktop-host-skip"></div>', unsafe_allow_html=True)

    if not _is_mobile_at:
        _at_consume_inline_form_dialog_actions(session, txn_type, cats, vendors)

    # ── SUBMISSION HANDLER (desktop + mobile) ─────────────────────────────────
    _mob_save_pending = _at_consume_mobile_save_pending() if _is_mobile_at else False
    if submitted or _mob_save_pending:
        _submit_type = (
            _at_effective_txn_type(_TYPE_NAMES)
            if _mob_save_pending
            else _TYPE_NAMES[st.session_state["at_type_idx"]]
        )
        _at_process_submit(
            session,
            currency_default=currency_default,
            vendors=vendors,
            bank_accounts=bank_accounts,
            open_sales=open_sales,
            txn_type=_submit_type,
            _TYPE_DISPLAY_MAP=_TYPE_DISPLAY_MAP,
        )

    # ── RECENT TRANSACTIONS SECTION (desktop) ─────────────────────────────────
    with st.container(key="erp_at_recent_host"):
        st.markdown("<div style='margin-top:20px;'></div>", unsafe_allow_html=True)
        _at_render_recent(session, currency_default)



def _at_save(
    session, txn_type, date, amount, currency, payment_method, notes,
    customer_name, category, vendor_name,
    invoice_choices, invoice_choice_val, open_sales,
    bank_sub, bank_acct_val, bank_dest_val, bank_accounts, vendors,
    tx_category_id=None, tx_subcategory_id=None,
    subcats_list=None, at_subcat_name=None,
    fx_rate: float = 1.0,
    card_bank_acct_val: str = None,
    bank_payment_acct_val: str = None,
    selected_payable_id: int = None,
    credit_card_account_id: int | None = None,
):
    """Route to the correct posting function based on transaction type."""

    if txn_type in ("Expense", "Purchase", "Supplier Payment"):
        _cc_err = _validate_company_cc_card(session, payment_method, credit_card_account_id)
        if _cc_err:
            st.error(_cc_err)
            _at_set_flash("error", _cc_err)
            return

    # Determine the best GL-mapping string: prefer subcategory name, fallback to category
    subcats_list = subcats_list or []
    subcat_name_for_gl = None
    if at_subcat_name and subcats_list:
        subcat_name_for_gl = at_subcat_name
    gl_category = subcat_name_for_gl or category

    # Capture the logged-in user for audit trail (Block 6)
    _uid = (_current_user() or {}).get("id")

    # Compute native amount (Step 1.3)
    _reporting_ccy = load_settings().get("currency", "TRY")
    _native = round(amount * fx_rate, 2) if fx_rate and fx_rate != 1.0 else amount

    if txn_type == "Sale":
        sale_type = payment_method  # "Cash", "Card", or "Credit" — stored as-is
        sale_date = date if isinstance(date, datetime.date) else _at_resolve_submit_date()
        ts = datetime.datetime.now().strftime("%Y%m%d%H%M%S")
        inv_num = f"INV-{ts}"
        _cname = customer_name.strip() or "Walk-in Customer"
        # Resolve customer_id if the name matches a known customer record
        _cust_obj = cq(session, Customer).filter_by(name=_cname, is_active=True).first()
        record = Sale(
            date=sale_date,
            invoice_number=inv_num,
            customer_name=_cname,
            description=notes.strip(),
            amount=amount,
            sale_type=sale_type,
            paid_amount=amount if sale_type != "Credit" else 0.0,
            balance=0.0 if sale_type != "Credit" else amount,
            due_date=sale_date if sale_type != "Credit" else sale_date + datetime.timedelta(days=30),
            status="Paid" if sale_type != "Credit" else "Open",
            tx_category_id=tx_category_id,
            tx_subcategory_id=tx_subcategory_id,
            created_by_id=_uid,
            customer_id=_cust_obj.id if _cust_obj else None,
            currency=currency, fx_rate=fx_rate, native_amount=_native,
        )
        session.add(record)
        session.commit()
        _sale_audit_logged = False
        if sale_type == "Card":
            post_card_sale(session, record.id, amount, sale_date, currency=currency, fx_rate=fx_rate)
            # Also update the named bank account balance so the dashboard reflects it.
            # Phase 18-MVP-1: when card settlement routing is ON the money is not in
            # the bank yet (it settles later), so skip the deposit + balance bump.
            if not _card_settlement_on(session) and card_bank_acct_val and bank_accounts:
                _card_ba = next((a for a in bank_accounts if a.name == card_bank_acct_val), None)
                if _card_ba:
                    _card_ba.balance = (_card_ba.balance or 0) + amount
                    session.add(BankTransaction(
                        account_id=_card_ba.id,
                        date=sale_date,
                        amount=amount,
                        type="deposit",
                        description=f"Card Sale {inv_num}",
                    ))
                    session.commit()
        elif sale_type == "Cash":
            if _commit_modes.is_boundary_mode(_commit_modes.POST_CASH_SALE_FAMILY):
                with boundary_commit_scope(session, _commit_modes.POST_CASH_SALE_FAMILY):
                    post_cash_sale(session, record.id, amount, sale_date, currency=currency, fx_rate=fx_rate)
                    log_audit(session, "Create", "Sale", record.id, f"Sale {inv_num} · {amount:,.2f} {currency}")
                    _sale_audit_logged = True
            else:
                post_cash_sale(session, record.id, amount, sale_date, currency=currency, fx_rate=fx_rate)
        else:
            post_credit_sale(session, record.id, amount, sale_date, currency=currency, fx_rate=fx_rate)
        if not _sale_audit_logged:
            log_audit(session, "Create", "Sale", record.id, f"Sale {inv_num} · {amount:,.2f} {currency}")
        st.success(_t("txn.sale_recorded", invoice=inv_num))
        _mark_at_save_succeeded()

    elif txn_type == "Expense":
        if st.session_state.get("at_expense_mode") == "worker":
            worker_id = st.session_state.get("at_worker_id")
            wm_type = st.session_state.get("at_worker_mv_type", "Salary")
            if not worker_id:
                st.error(_t("txn.expense_worker_required"))
                return
            ba, ba_err = _bank_account_for_worker_payment(
                session,
                payment_method,
                currency=currency,
                preferred_name=bank_payment_acct_val,
            )
            if not ba:
                st.error(ba_err or _t("form.no_bank_accounts"))
                return
            if wm_type == "Salary":
                gross = _parse_amount_str(st.session_state.get("at_worker_gross", ""))
                ded = _parse_amount_str(st.session_state.get("at_worker_ded", "")) or 0.0
                adv_rec = (
                    _parse_amount_str(st.session_state.get("at_worker_adv_rec", "")) or 0.0
                )
                if not gross or gross <= 0:
                    st.error(_t("txn.invalid_amount_zero"))
                    return
                net_paid = round(max(gross - ded - adv_rec, 0.0), 2)
                if abs(net_paid - round(amount, 2)) > 0.01:
                    st.error(
                        _t(
                            "banking.import.match.worker_net_mismatch",
                            bank=f"{amount:,.2f}",
                            net=f"{net_paid:,.2f}",
                        )
                    )
                    return
                mv_id, err = post_worker_movement(
                    session,
                    worker_id,
                    "Salary",
                    date,
                    bank_account_id=ba.id,
                    gross_salary=gross,
                    deductions=ded,
                    advance_recovery=adv_rec,
                    pay_period=st.session_state.get("at_worker_period"),
                    notes=notes.strip() or None,
                    created_by_id=_uid,
                )
            else:
                mv_id, err = post_worker_movement(
                    session,
                    worker_id,
                    "Advance",
                    date,
                    bank_account_id=ba.id,
                    amount=amount,
                    notes=notes.strip() or None,
                    created_by_id=_uid,
                )
            if err:
                st.error(err)
                return
            worker = session.get(Worker, worker_id)
            wname = worker.name if worker else "—"
            log_audit(
                session,
                "Create",
                "WorkerMovement",
                mv_id,
                f"{wm_type}: {wname} · {amount:,.2f} {currency}",
            )
            st.success(
                _t(
                    "txn.expense_worker_recorded",
                    name=wname,
                    type=_i18n_db(_WORKER_MOVEMENT_TYPE_I18N, wm_type),
                )
            )
            _mark_at_save_succeeded()
            return

        record = ExpenseRecord(
            date=date,
            expense_type=category,
            category=gl_category,
            description=notes.strip(),
            amount=amount,
            payment_method=payment_method,
            gross_salary=amount,
            deductions=0.0,
            net_salary=amount,
            tx_category_id=tx_category_id,
            tx_subcategory_id=tx_subcategory_id,
            created_by_id=_uid,
            currency=currency, fx_rate=fx_rate, native_amount=_native,
            company_id=_current_company_id(),
        )
        ok, err = _save_and_post_expense_record(
            session,
            record,
            category=gl_category,
            payment_method=payment_method,
            credit_card_account_id=credit_card_account_id,
        )
        if not ok:
            _err = err or _t("txn.save_failed", error="expense")
            st.error(_err)
            _at_set_flash("error", _err)
            return
        if payment_method == "Bank":
            _record_named_bank_movement(
                session,
                bank_accounts,
                bank_payment_acct_val,
                amount=amount,
                date=date,
                description=f"Expense EXP#{record.id} — {category}",
                txn_type="withdrawal",
            )
            session.commit()
        log_audit(session, "Create", "ExpenseRecord", record.id, f"{category} expense · {amount:,.2f} {currency}")
        _flush_pending_attachment(session, "ExpenseRecord", record.id)
        _exp_ok = _t("txn.expense_recorded", category=category)
        st.success(_exp_ok)
        _mark_at_save_succeeded(_exp_ok)

    elif txn_type == "Purchase":
        if not vendors or not vendor_name:
            st.error(_t("txn.vendor_required"))
            return
        vendor = next((v for v in vendors if v.name == vendor_name), None)
        if not vendor:
            st.error(_t("form.vendor_not_found"))
            return
        gl_debit = category if category else "Inventory"
        record = Purchase(
            date=date,
            vendor_id=vendor.id,
            amount=amount,
            description=notes.strip(),
            purchase_type=payment_method,
            gl_debit=gl_debit,
            tx_category_id=tx_category_id,
            tx_subcategory_id=tx_subcategory_id,
            created_by_id=_uid,
            currency=currency, fx_rate=fx_rate, native_amount=_native,
            credit_card_account_id=credit_card_account_id if payment_method == _COMPANY_CC_METHOD else None,
        )
        session.add(record)
        session.commit()
        try:
            post_purchase(
                session, record.id, amount, date, payment_method, gl_debit,
                currency=currency, fx_rate=fx_rate,
                credit_card_account_id=credit_card_account_id,
            )
        except ValueError as exc:
            st.error(str(exc))
            return
        if payment_method == "Credit":
            payable = Payable(
                date=date,
                vendor_id=vendor.id,
                amount=amount,
                due_date=date + datetime.timedelta(days=30),
                paid=False,
                description=f"From Purchase #{record.id}: {notes.strip()}",
                expense_category=gl_debit,
                purchase_id=record.id,
            )
            session.add(payable)
            session.commit()
            log_audit(session, "Create", "Purchase", record.id, f"PUR#{record.id} · {amount:,.2f} {currency} — payable created")
            _flush_pending_attachment(session, "Purchase", record.id)
            st.success(_t("txn.purchase_recorded_payable", id=record.id))
            _mark_at_save_succeeded()
        else:
            if payment_method == "Bank":
                _record_named_bank_movement(
                    session,
                    bank_accounts,
                    bank_payment_acct_val,
                    amount=amount,
                    date=date,
                    description=f"Purchase PUR#{record.id}",
                    txn_type="withdrawal",
                )
                session.commit()
            log_audit(session, "Create", "Purchase", record.id, f"PUR#{record.id} · {amount:,.2f} {currency}")
            _flush_pending_attachment(session, "Purchase", record.id)
            st.success(_t("txn.purchase_recorded", id=record.id))
            _mark_at_save_succeeded()

    elif txn_type == "Supplier Payment":
        if not vendors or not vendor_name:
            st.error(_t("txn.vendor_required"))
            return
        vendor = next((v for v in vendors if v.name == vendor_name), None)
        if not vendor:
            st.error(_t("form.vendor_not_found"))
            return
        # Require an explicit payable selection — no silent auto-pick fallback
        if not selected_payable_id:
            st.error(_t("txn.payable_none_selected"))
            return
        payable = session.get(Payable, selected_payable_id)
        if not payable:
            st.error(_t("txn.payable_missing"))
            return
        if payable.is_void:
            st.error(_t("txn.payable_voided"))
            return
        if payable.vendor_id != vendor.id:
            st.error(_t("txn.payable_wrong_vendor"))
            return
        pay_err = _validate_payable_payment_amount(payable, amount, currency=currency)
        if pay_err:
            st.error(pay_err)
            return
        payable.payment_method = payment_method
        if payment_method == _COMPANY_CC_METHOD:
            payable.credit_card_account_id = credit_card_account_id
        _apply_payable_payment_state(payable, amount)
        session.commit()
        try:
            post_payable_payment(
                session, payable.id, amount, date, payment_method, currency=currency,
                credit_card_account_id=credit_card_account_id,
            )
        except ValueError as exc:
            st.error(str(exc))
            return
        if payment_method == "Bank":
            _record_named_bank_movement(
                session,
                bank_accounts,
                bank_payment_acct_val,
                amount=amount,
                date=date,
                description=f"Supplier payment PAY#{payable.id}",
                txn_type="withdrawal",
            )
            session.commit()
        log_audit(session, "Payment", "Payable", payable.id,
                  f"Payable #{payable.id} paid · {amount:,.2f} {currency}")
        st.success(_t("txn.payment_recorded", id=payable.id))
        _mark_at_save_succeeded()

    elif txn_type == "Customer Payment":
        if not open_sales or invoice_choice_val is None:
            st.error(_t("txn.invoice_not_selected"))
            return
        try:
            idx = invoice_choices.index(invoice_choice_val)
        except ValueError:
            st.error(_t("txn.invoice_not_found"))
            return
        sale = open_sales[idx]
        err = post_receivable_payment(session, sale.id, amount, date, payment_method, currency=currency)
        if err:
            st.error(err)
        else:
            if payment_method == "Bank":
                _record_named_bank_movement(
                    session,
                    bank_accounts,
                    bank_payment_acct_val,
                    amount=amount,
                    date=date,
                    description=f"Customer payment {sale.invoice_number}",
                    txn_type="deposit",
                )
                session.commit()
            log_audit(session, "Payment", "Sale", sale.id,
                      f"Payment {amount:,.2f} {currency} on {sale.invoice_number}")
            st.success(_t("txn.customer_payment", amount=amount, invoice=sale.invoice_number))
            _mark_at_save_succeeded()

    elif txn_type == "Bank Transaction":
        if not bank_accounts or not bank_acct_val:
            st.error(_t("txn.bank_not_selected"))
            return
        acct = next((a for a in bank_accounts if a.name == bank_acct_val), None)
        if not acct:
            st.error(_t("txn.bank_not_found"))
            return
        ttype = bank_sub.lower()
        if ttype == "transfer":
            if not bank_dest_val or bank_dest_val == bank_acct_val:
                st.error(_t("bank.err.dest_account"))
                return
            dest = next((a for a in bank_accounts if a.name == bank_dest_val), None)
            if not dest:
                st.error(_t("txn.bank_not_found"))
                return
            acct.balance = (acct.balance or 0) - amount
            dest.balance = (dest.balance or 0) + amount
            txn = BankTransaction(
                account_id=acct.id, date=date, amount=amount,
                type="transfer", description=notes.strip(),
            )
            txn2 = BankTransaction(
                account_id=dest.id, date=date, amount=amount,
                type="transfer",
                description=f"Transfer from {acct.name}: {notes.strip()}",
            )
            session.add_all([txn, txn2])
            session.commit()
            post_bank_transfer(session, txn.id, amount, date, acct.name, dest.name)
            log_audit(session, "Create", "BankTransaction", txn.id,
                      f"Transfer {amount:,.2f} from {acct.name} → {dest.name}")
            st.success(_t("txn.transfer_recorded", amount=amount, from_acct=acct.name, to_acct=dest.name))
            _mark_at_save_succeeded()
        else:
            if ttype == "deposit":
                acct.balance = (acct.balance or 0) + amount
            else:
                acct.balance = (acct.balance or 0) - amount
            txn = BankTransaction(
                account_id=acct.id, date=date, amount=amount,
                type=ttype, description=notes.strip(),
            )
            session.add(txn)
            session.commit()
            post_bank_transaction(session, txn.id, amount, date, ttype, currency=currency)
            log_audit(session, "Create", "BankTransaction", txn.id,
                      f"Bank {bank_sub} {amount:,.2f} {currency} — {acct.name}")
            _bk = bank_sub.lower()
            _bk_key = "txn.bank_deposit_recorded" if _bk == "deposit" else "txn.bank_withdrawal_recorded" if _bk == "withdrawal" else "txn.bank_transfer_recorded"
            st.success(_t(_bk_key, amount=amount))
            _mark_at_save_succeeded()


def _at_render_recent(session, currency):
    """Show last 10 transactions as styled card rows."""
    rows = []
    for s in cq(session, Sale).filter_by(is_void=False).order_by(Sale.date.desc()).limit(5).all():
        rows.append({"Date": s.date, "Type": f"Sale ({s.sale_type})", "Reference": s.invoice_number,
                     "Party": s.customer_name, "Amount": s.amount, "Direction": "in", "Status": s.status})
    for e in cq(session, ExpenseRecord).filter_by(is_void=False).order_by(ExpenseRecord.date.desc()).limit(5).all():
        rows.append({"Date": e.date, "Type": f"Expense ({e.expense_type})", "Reference": f"EXP#{e.id}",
                     "Party": e.employee_name or e.category or "—", "Amount": e.amount, "Direction": "out", "Status": "Recorded"})
    for p in cq(session, Purchase).filter_by(is_void=False).order_by(Purchase.date.desc()).limit(5).all():
        vendor = session.get(Vendor, p.vendor_id)
        rows.append({"Date": p.date, "Type": f"Purchase ({p.purchase_type})", "Reference": f"PUR#{p.id}",
                     "Party": vendor.name if vendor else "—", "Amount": p.amount, "Direction": "out", "Status": "Active"})
    for b in cq(session, BankTransaction).filter_by(is_void=False).order_by(BankTransaction.date.desc()).limit(3).all():
        acct = session.get(BankAccount, b.account_id)
        rows.append({"Date": b.date, "Type": f"Bank {b.type.title()}", "Reference": f"BNK#{b.id}",
                     "Party": acct.name if acct else "—", "Amount": b.amount, "Direction": "in" if b.type == "deposit" else "out", "Status": "Active"})

    if not rows:
        st.info(_t("txn.no_transactions"))
        return

    rows = sorted(rows, key=lambda x: x["Date"], reverse=True)[:10]

    with st.container(border=True):
        st.markdown(
            section_header_html(_t("txn.recent_transactions"), accent="info"),
            unsafe_allow_html=True,
        )
        _PILL_VARIANT = {
            "Paid": "success",
            "Open": "warning",
            "Overdue": "danger",
            "Partial": "info",
            "Recorded": "info",
            "Active": "neutral",
        }
        _rows_html = ""
        for r in rows:
            icon = "🧾" if r["Direction"] == "in" else ("🛒" if "Purchase" in r["Type"] else "💳")
            icon_bg = ("color-mix(in srgb,var(--theme-success)12%,var(--theme-card)88%)" if r["Direction"] == "in" else
                       ("color-mix(in srgb,var(--theme-info)12%,var(--theme-card)88%)" if "Purchase" in r["Type"] else
                        "color-mix(in srgb,var(--theme-danger)12%,var(--theme-card)88%)"))
            amt_variant = "in" if r["Direction"] == "in" else "out"
            amt_sign  = "+" if r["Direction"] == "in" else "−"
            date_str  = r["Date"].strftime("%d %b") if hasattr(r["Date"], "strftime") else str(r["Date"])
            status_pill = mobile_status_pill_html(
                r["Status"],
                variant=_PILL_VARIANT.get(r["Status"], "neutral"),
            )
            _rows_html += mobile_list_row_html(
                str(r["Party"]),
                subtitle=f'{r["Type"]} · {r["Reference"]}',
                amount=f'{amt_sign}{currency} {r["Amount"]:,.2f}',
                amount_variant=amt_variant,
                meta_sub=date_str,
                title_extra_html=f' {status_pill}',
                icon_block=(
                    f'<div class="erp-mob-at-row-icon" style="background:{icon_bg};">{icon}</div>'
                ),
            )
        st.markdown(_rows_html, unsafe_allow_html=True)


# ─────────────────────────────────────────────────────────────────────────────
# Transaction correction helpers
# ─────────────────────────────────────────────────────────────────────────────

def edit_sale(session, sale_id, fields: dict):
    """Edit a Sale. Tier 2 fields (date/amount/sale_type) reverse and re-post GL."""
    sale = session.get(Sale, sale_id)
    if not sale:
        return False, "Sale not found."
    if sale.is_void:
        return False, "Cannot edit a voided sale."
    tier2 = {"date", "amount", "sale_type"}
    tier2_changed = any(k in fields for k in tier2)
    if tier2_changed and sale.paid_amount > 0 and sale.sale_type == "Credit":
        return False, "This invoice has a recorded payment. Void and re-enter to correct it."
    if tier2_changed:
        locked = (
            cq(session, FiscalPeriod)
            .filter(FiscalPeriod.is_closed == True,
                    FiscalPeriod.start_date <= sale.date,
                    FiscalPeriod.end_date >= sale.date)
            .first()
        )
        if locked:
            return False, f"Period '{locked.name}' is closed. Void and re-enter to correct this transaction."
    _keys = ("date", "amount", "sale_type", "customer_name", "description", "tx_category_id", "tx_subcategory_id")
    before = {k: getattr(sale, k) for k in _keys}
    before["date"] = str(before["date"])
    if tier2_changed:
        orig_type = sale.sale_type
        _orig_ref = {"Cash": "CashSale", "Card": "CardSale"}.get(orig_type, "CreditSale")
        reverse_journal_entries_for(session, _orig_ref, sale_id, "Correction")
    for k, v in fields.items():
        setattr(sale, k, v)
    if tier2_changed:
        if sale.sale_type != "Credit":
            sale.paid_amount, sale.balance, sale.status, sale.due_date = sale.amount, 0.0, "Paid", sale.date
        else:
            sale.paid_amount, sale.balance, sale.status = 0.0, sale.amount, "Open"
            sale.due_date = sale.date + datetime.timedelta(days=30)
        session.flush()
        if sale.sale_type == "Card":
            post_card_sale(session, sale_id, sale.amount, sale.date)
        elif sale.sale_type == "Cash":
            post_cash_sale(session, sale_id, sale.amount, sale.date)
        else:
            post_credit_sale(session, sale_id, sale.amount, sale.date)
    else:
        session.flush()
        session.commit()
    after = {k: getattr(sale, k) for k in _keys}
    after["date"] = str(after["date"])
    diff = {k for k in _keys if str(before[k]) != str(after[k])}
    log_audit(session, "Edit", "Sale", sale_id, json.dumps({
        "before": {k: before[k] for k in diff},
        "after": {k: after[k] for k in diff},
        "user": load_settings().get("company_name", ""),
        "edited_at": datetime.datetime.now().isoformat(),
    }))
    return True, None


def edit_expense(session, expense_id, fields: dict):
    """Edit an ExpenseRecord. Tier 2 fields (date/amount/payment_method) reverse and re-post GL."""
    expense = session.get(ExpenseRecord, expense_id)
    if not expense:
        return False, "Expense not found."
    if expense.is_void:
        return False, "Cannot edit a voided expense."
    tier2 = {"date", "amount", "payment_method", "credit_card_account_id"}
    tier2_changed = any(k in fields for k in tier2)
    if tier2_changed:
        locked = (
            cq(session, FiscalPeriod)
            .filter(FiscalPeriod.is_closed == True,
                    FiscalPeriod.start_date <= expense.date,
                    FiscalPeriod.end_date >= expense.date)
            .first()
        )
        if locked:
            return False, f"Period '{locked.name}' is closed. Void and re-enter to correct this transaction."
    _keys = ("date", "amount", "payment_method", "credit_card_account_id", "description", "expense_type", "tx_category_id", "tx_subcategory_id")
    before = {k: getattr(expense, k) for k in _keys}
    before["date"] = str(before["date"])
    was_cc = (expense.payment_method or "") == _COMPANY_CC_METHOD
    if tier2_changed:
        if was_cc:
            reverse_cc_subledgers_for_gl_reference(session, "Expense", expense_id, "Correction")
        reverse_journal_entries_for(session, "Expense", expense_id, "Correction")
    for k, v in fields.items():
        setattr(expense, k, v)
    if tier2_changed:
        session.flush()
        post_expense(
            session, expense_id, expense.amount, expense.date,
            expense.category or expense.expense_type or "Office",
            payment_method=expense.payment_method or "Cash",
            credit_card_account_id=expense.credit_card_account_id,
        )
    else:
        session.flush()
        session.commit()
    after = {k: getattr(expense, k) for k in _keys}
    after["date"] = str(after["date"])
    diff = {k for k in _keys if str(before[k]) != str(after[k])}
    log_audit(session, "Edit", "ExpenseRecord", expense_id, json.dumps({
        "before": {k: before[k] for k in diff},
        "after": {k: after[k] for k in diff},
        "user": load_settings().get("company_name", ""),
        "edited_at": datetime.datetime.now().isoformat(),
    }))
    return True, None


def edit_purchase(session, purchase_id, fields: dict):
    """Edit a Purchase. Tier 2 fields (date/amount/purchase_type) reverse and re-post GL."""
    purchase = session.get(Purchase, purchase_id)
    if not purchase:
        return False, "Purchase not found."
    if purchase.is_void:
        return False, "Cannot edit a voided purchase."
    orig_pt = purchase.purchase_type or "Credit"
    tier2 = {"date", "amount", "purchase_type", "credit_card_account_id"}
    tier2_changed = any(k in fields for k in tier2)
    if tier2_changed:
        linked = _linked_purchase_payable(session, purchase_id)
        if linked and linked.paid and not linked.is_void:
            return False, "The linked payable is already paid. Void and re-enter to correct this transaction."
    if tier2_changed:
        locked = (
            cq(session, FiscalPeriod)
            .filter(FiscalPeriod.is_closed == True,
                    FiscalPeriod.start_date <= purchase.date,
                    FiscalPeriod.end_date >= purchase.date)
            .first()
        )
        if locked:
            return False, f"Period '{locked.name}' is closed. Void and re-enter to correct this transaction."
    _keys = ("date", "amount", "purchase_type", "credit_card_account_id", "vendor_id", "description", "gl_debit", "tx_category_id", "tx_subcategory_id")
    before = {k: getattr(purchase, k) for k in _keys}
    before["date"] = str(before["date"])
    was_cc = (purchase.purchase_type or "") == _COMPANY_CC_METHOD
    if tier2_changed:
        if was_cc:
            reverse_cc_subledgers_for_gl_reference(
                session, _purchase_ref_type(purchase.purchase_type), purchase_id, "Correction"
            )
        reverse_journal_entries_for(
            session, _purchase_ref_type(purchase.purchase_type), purchase_id, "Correction"
        )
    for k, v in fields.items():
        setattr(purchase, k, v)
    if tier2_changed:
        session.flush()
        post_purchase(
            session, purchase_id, purchase.amount, purchase.date,
            purchase.purchase_type or "Credit", purchase.gl_debit or NAV_INVENTORY,
            credit_card_account_id=purchase.credit_card_account_id,
        )
    _sync_purchase_payable_lifecycle(session, purchase, orig_pt)
    session.commit()
    after = {k: getattr(purchase, k) for k in _keys}
    after["date"] = str(after["date"])
    diff = {k for k in _keys if str(before[k]) != str(after[k])}
    log_audit(session, "Edit", "Purchase", purchase_id, json.dumps({
        "before": {k: before[k] for k in diff},
        "after": {k: after[k] for k in diff},
        "user": load_settings().get("company_name", ""),
        "edited_at": datetime.datetime.now().isoformat(),
    }))
    return True, None


_TXH_STATUS_VARIANT = {
    "Paid": "success",
    "Open": "warning",
    "Overdue": "danger",
    "Partial": "info",
    "Recorded": "info",
    "Active": "neutral",
    "VOID": "void",
}
_TXH_TYPE_ICON = {
    "Cash Sale": "🧾",
    "Card Sale": "🧾",
    "Credit Sale": "🧾",
    "Expense": "💳",
    "Purchase": "🛒",
    "Bank Deposit": "🏦",
    "Bank Withdrawal": "🏦",
    "Bank Transfer": "🏦",
    "Payable": "📌",
}
_TXH_INFLOW_TYPES = frozenset({
    "Cash Sale", "Card Sale", "Credit Sale", "Bank Deposit",
})

# Desktop table column weights — keep in sync with grid in ui/desktop_txn_history.css
_TXH_DESKTOP_COL_WEIGHTS = [0.68, 0.88, 1.05, 3.4, 1.2, 0.92, 0.72]


def _txh_row_icon_class(txn_type_key: str) -> str:
    if txn_type_key in _TXH_INFLOW_TYPES:
        return "erp-txh-row-icon erp-txh-row-icon--in"
    if txn_type_key in ("Expense", "Bank Withdrawal"):
        return "erp-txh-row-icon erp-txh-row-icon--out"
    return "erp-txh-row-icon erp-txh-row-icon--neutral"


_TXH_EDITABLE_TYPES = frozenset({"Sale", "ExpenseRecord", "Purchase"})

_TXH_REPEAT_ELIGIBLE_ETYPES = frozenset({"ExpenseRecord", "Purchase"})
_TXH_REPEAT_TYPE_IDX = {"ExpenseRecord": 1, "Purchase": 2}
_TXH_REPEAT_TXN_TYPE = {"ExpenseRecord": "Expense", "Purchase": "Purchase"}


def _txh_expense_is_repeat_ineligible(eobj) -> bool:
    """Salary and worker-linked expense rows are out of scope for Repeat v1."""
    if (getattr(eobj, "expense_type", None) or "").strip() == "Salary":
        return True
    if (getattr(eobj, "employee_name", None) or "").strip():
        return True
    return False


def _txh_repeat_company_ok(eobj) -> bool:
    active = _current_company_id()
    if active is None:
        return True
    rec_co = getattr(eobj, "company_id", None)
    return rec_co is None or rec_co == active


def _txh_repeat_eligible(etype: str, eobj, *, is_void_row: bool) -> bool:
    if is_void_row or getattr(eobj, "is_void", False):
        return False
    if not _txh_repeat_company_ok(eobj):
        return False
    if etype not in _TXH_REPEAT_ELIGIBLE_ETYPES:
        return False
    if etype == "ExpenseRecord" and _txh_expense_is_repeat_ineligible(eobj):
        return False
    return _can("edit_transaction")


def _txh_resolve_active_category(session, cat_id: int | None, txn_type: str):
    if not cat_id:
        return None
    cat = session.get(TransactionCategory, cat_id)
    if not cat or not cat.is_active or cat.transaction_type != txn_type:
        return None
    return cat


def _txh_resolve_active_subcategory(session, subcat_id: int | None, cat_id: int | None):
    if not subcat_id or not cat_id:
        return None
    sub = session.get(TransactionSubcategory, subcat_id)
    if not sub or not sub.is_active or sub.category_id != cat_id:
        return None
    return sub


def _txh_resolve_active_vendor(session, vendor_id: int | None):
    if not vendor_id:
        return None
    vendor = session.get(Vendor, vendor_id)
    if not vendor or not vendor.is_active:
        return None
    return vendor


def _txh_coerce_repeat_payment_method(session, txn_type: str, raw_pm: str | None) -> str:
    allowed = _at_allowed_pay_methods(session, txn_type)
    if raw_pm and raw_pm in allowed:
        return raw_pm
    return _at_default_pay_method(session, txn_type)


def _txh_clear_repeat_forbidden_session_keys() -> None:
    """Strip AT keys Repeat must never copy from a prior draft or source row."""
    for _k in (
        "at_cust",
        "at_cust_sel",
        "at_worker_id",
        "at_payable_id",
        "at_inv",
        "at_bank_acct",
        "at_bank_dest",
        "at_bank_sub",
        "at_fx_rate_val",
        "mob_at_worker_gross",
        "mob_at_worker_ded",
        "mob_at_worker_adv_rec",
        "at_worker_gross",
        "at_worker_ded",
        "at_worker_adv_rec",
        "at_worker_mv_type",
        "mob_at_inv_sel",
        "mob_at_payable_sel",
        "_at_save_succeeded",
        "_at_submit_pending",
        "mob_at_save_clicked",
    ):
        st.session_state.pop(_k, None)
    st.session_state["at_expense_mode"] = "general"


def _txh_apply_repeat_prefill(session, etype: str, eobj) -> bool:
    """Prefill Add Transaction from an eligible history row. No save/posting."""
    if not _txh_repeat_eligible(etype, eobj, is_void_row=getattr(eobj, "is_void", False)):
        return False

    txn_type = _TXH_REPEAT_TXN_TYPE[etype]
    type_idx = _TXH_REPEAT_TYPE_IDX[etype]
    settings = load_settings()
    currency_default = settings.get("currency", "TRY")

    _txh_clear_repeat_forbidden_session_keys()

    cat = _txh_resolve_active_category(session, eobj.tx_category_id, txn_type)
    sub = _txh_resolve_active_subcategory(
        session, eobj.tx_subcategory_id, cat.id if cat else None
    )

    if etype == "ExpenseRecord":
        raw_pm = eobj.payment_method
    else:
        raw_pm = eobj.purchase_type or "Credit"
    coerced_pm = _txh_coerce_repeat_payment_method(session, txn_type, raw_pm)

    amount = eobj.amount
    notes = (eobj.description or "").strip()
    currency = (getattr(eobj, "currency", None) or "").strip() or currency_default

    st.session_state["at_type_idx"] = type_idx
    st.session_state["mob_at_tab"] = type_idx
    st.session_state.pop("mob_at_more_idx", None)
    st.session_state["at_date"] = datetime.date.today()
    st.session_state["at_date_follows_today"] = True
    st.session_state["at_amount_display"] = str(amount) if amount is not None else ""
    st.session_state["at_notes_field"] = notes
    st.session_state["at_currency"] = currency
    st.session_state["at_pm"] = coerced_pm
    _at_clear_stale_payment_account_keys(coerced_pm)

    if cat:
        st.session_state["mob_at_cat_id"] = cat.id
        st.session_state["at_cat"] = cat.name
        st.session_state["at_last_cat_id"] = cat.id
        st.session_state.pop("mob_at_cat_name", None)
    else:
        for _k in ("mob_at_cat_id", "at_cat", "at_last_cat_id", "mob_at_cat_name"):
            st.session_state.pop(_k, None)

    if sub:
        st.session_state["mob_at_subcat_id"] = sub.id
        st.session_state["at_subcat"] = sub.name
    else:
        st.session_state.pop("mob_at_subcat_id", None)
        st.session_state.pop("at_subcat", None)

    st.session_state.pop("at_vendor", None)
    st.session_state.pop("mob_at_vendor_sel", None)
    if etype == "Purchase":
        vendor = _txh_resolve_active_vendor(session, eobj.vendor_id)
        if vendor:
            st.session_state["at_vendor"] = vendor.name
            st.session_state["mob_at_vendor_sel"] = vendor.name

    st.session_state.pop("mob_at_picker", None)
    st.session_state.pop("mob_at_picker_search", None)
    st.session_state["nav_selection"] = NAV_NEW_TRANSACTION
    _mobile_close_app_surfaces()
    st.session_state["sidebar_group"] = None
    return True


def _txh_created_by_display(user_lkp: dict, source) -> str:
    """Resolve Created By from the row source object; safe when id is missing."""
    created_by_id = getattr(source, "created_by_id", None)
    return user_lkp.get(created_by_id, "—")


def _txh_fetch_filtered_rows(
    session,
    *,
    start_date: datetime.date,
    end_date: datetime.date,
    keyword: str,
    type_filter: str,
    method_filter: str,
    cat_filter: str,
    subcat_filter: str,
    show_voided: bool,
    currency: str,
    cat_names_lkp: dict,
    subcat_names_lkp: dict,
    user_lkp: dict,
    txh_all: str,
) -> list[tuple[dict, str, object]]:
    """Shared query + filter logic — identical rows for mobile and desktop."""
    rows: list[tuple[dict, str, object]] = []

    if type_filter in (txh_all, "Sale"):
        _q = cq(session, Sale).filter(Sale.date.between(start_date, end_date))
        if not show_voided:
            _q = _q.filter(Sale.is_void == False)
        for s in _q.order_by(Sale.date.desc()).all():
            if not _txh_matches_keyword(
                keyword,
                party=s.customer_name,
                description=s.description or "",
                txn_type=s.sale_type + " Sale",
                method=s.sale_type,
                reference=s.invoice_number,
                amount=float(s.amount or 0),
            ):
                continue
            cat_label = cat_names_lkp.get(s.tx_category_id, "")
            sub_label = subcat_names_lkp.get(s.tx_subcategory_id, "")
            if cat_filter != txh_all and cat_label != cat_filter:
                continue
            if subcat_filter != txh_all and sub_label != subcat_filter:
                continue
            rows.append(({
                "Date": s.date, "Type": s.sale_type + " Sale",
                "Reference": s.invoice_number, "Party": s.customer_name,
                "Category": cat_label, "Subcategory": sub_label,
                "Amount": s.amount, "Currency": currency,
                "Method": s.sale_type, "Description": s.description or "",
                "Status": "VOID" if s.is_void else s.status,
                "Created By": _txh_created_by_display(user_lkp, s),
            }, "Sale", s))

    if type_filter in (txh_all, "Expense"):
        _q = cq(session, ExpenseRecord).filter(ExpenseRecord.date.between(start_date, end_date))
        if not show_voided:
            _q = _q.filter(ExpenseRecord.is_void == False)
        for e in _q.order_by(ExpenseRecord.date.desc()).all():
            if method_filter != txh_all and (e.payment_method or "").lower() != method_filter.lower():
                continue
            if not _txh_matches_keyword(
                keyword,
                party=e.employee_name or "",
                description=e.description or "",
                txn_type=e.expense_type or "Expense",
                method=e.payment_method or "",
                reference=e.category or "",
                amount=float(e.amount or 0),
            ):
                continue
            cat_label = cat_names_lkp.get(e.tx_category_id, "")
            sub_label = subcat_names_lkp.get(e.tx_subcategory_id, "")
            if cat_filter != txh_all and cat_label != cat_filter:
                continue
            if subcat_filter != txh_all and sub_label != subcat_filter:
                continue
            rows.append(({
                "Date": e.date, "Type": e.expense_type or "Expense",
                "Reference": e.category or "", "Party": e.employee_name or "",
                "Category": cat_label, "Subcategory": sub_label,
                "Amount": e.amount, "Currency": currency,
                "Method": e.payment_method or "", "Description": e.description or "",
                "Status": "VOID" if e.is_void else "Recorded",
                "Created By": _txh_created_by_display(user_lkp, e),
            }, "ExpenseRecord", e))

    if type_filter in (txh_all, "Purchase"):
        _q = cq(session, Purchase).filter(Purchase.date.between(start_date, end_date))
        if not show_voided:
            _q = _q.filter(Purchase.is_void == False)
        for p in _q.order_by(Purchase.date.desc()).all():
            _vnd = session.get(Vendor, p.vendor_id)
            vname = _vnd.name if _vnd else ""
            if not _txh_matches_keyword(
                keyword,
                party=vname,
                description=p.description or "",
                txn_type="Purchase",
                method=p.purchase_type or "Credit",
                reference=f"PUR#{p.id}",
                amount=float(p.amount or 0),
            ):
                continue
            cat_label = cat_names_lkp.get(p.tx_category_id, "")
            sub_label = subcat_names_lkp.get(p.tx_subcategory_id, "")
            if cat_filter != txh_all and cat_label != cat_filter:
                continue
            if subcat_filter != txh_all and sub_label != subcat_filter:
                continue
            rows.append(({
                "Date": p.date, "Type": "Purchase",
                "Reference": f"PUR#{p.id}", "Party": vname,
                "Category": cat_label, "Subcategory": sub_label,
                "Amount": p.amount, "Currency": currency,
                "Method": p.purchase_type or "Credit", "Description": p.description or "",
                "Status": "VOID" if p.is_void else "Active",
                "Created By": _txh_created_by_display(user_lkp, p),
            }, "Purchase", p))

    if type_filter in (txh_all, "Banking"):
        _q = cq(session, BankTransaction).filter(BankTransaction.date.between(start_date, end_date))
        if not show_voided:
            _q = _q.filter(BankTransaction.is_void == False)
        for t in _q.order_by(BankTransaction.date.desc()).all():
            _acct = session.get(BankAccount, t.account_id)
            if not _txh_matches_keyword(
                keyword,
                party=_acct.name if _acct else "",
                description=t.description or "",
                txn_type="Bank " + t.type.title(),
                method="Bank",
                reference=f"TXN#{t.id}",
                amount=float(t.amount or 0),
            ):
                continue
            if cat_filter != txh_all:
                continue
            rows.append(({
                "Date": t.date, "Type": "Bank " + t.type.title(),
                "Reference": f"TXN#{t.id}", "Party": _acct.name if _acct else "",
                "Category": "", "Subcategory": "",
                "Amount": t.amount, "Currency": currency,
                "Method": "Bank", "Description": t.description or "",
                "Status": "VOID" if t.is_void else "Active",
            }, "BankTransaction", t))

    if type_filter in (txh_all, "Payable"):
        _q = cq(session, Payable).filter(Payable.date.between(start_date, end_date))
        if not show_voided:
            _q = _q.filter(Payable.is_void == False)
        for p in _q.order_by(Payable.date.desc()).all():
            _vnd = session.get(Vendor, p.vendor_id)
            vname = _vnd.name if _vnd else ""
            if not _txh_matches_keyword(
                keyword,
                party=vname,
                description=p.description or "",
                txn_type="Payable",
                method=p.payment_method or "Credit",
                reference=f"PAY#{p.id}",
                amount=float(p.amount or 0),
            ):
                continue
            if cat_filter != txh_all:
                continue
            rows.append(({
                "Date": p.date, "Type": "Payable",
                "Reference": f"PAY#{p.id}", "Party": vname,
                "Category": "", "Subcategory": "",
                "Amount": p.amount, "Currency": currency,
                "Method": p.payment_method or "Credit", "Description": p.description or "",
                "Status": "VOID" if p.is_void else ("Paid" if p.paid else "Open"),
            }, "Payable", p))

    return sorted(rows, key=lambda x: x[0]["Date"], reverse=True)


def _txh_rows_to_dataframe(rows: list[tuple[dict, str, object]]) -> pd.DataFrame:
    if not rows:
        return pd.DataFrame(columns=["Date", "Type", "Reference", "Party", "Category",
                                     "Subcategory", "Amount", "Currency", "Method",
                                     "Description", "Status"])
    return pd.DataFrame([r[0] for r in rows])


def _txh_truncate_text(text: str, limit: int = 56) -> str:
    raw = (text or "").strip()
    if len(raw) <= limit:
        return raw
    return raw[: limit - 1] + "…"


def _txh_status_pills_html(status: str, status_disp: str, *, is_corrected: bool, is_void_row: bool) -> str:
    variant = _TXH_STATUS_VARIANT.get(status, "neutral")
    parts = [mobile_status_pill_html(status_disp, variant=variant)]
    if is_corrected and not is_void_row:
        parts.append(
            mobile_status_pill_html(f'✱ {_t("txnrow.corrected")}', variant="corrected")
        )
    return (
        f'<span class="erp-mob-status-pill-row erp-txh-row-pills">'
        f'{"".join(parts)}</span>'
    )


def _txh_action_defs(etype: str, eobj, *, is_void_row: bool) -> dict[str, bool]:
    """Shared action permissions — no presentation."""
    can_write = _can("edit_transaction")
    editable = etype in _TXH_EDITABLE_TYPES
    can_repeat = _txh_repeat_eligible(etype, eobj, is_void_row=is_void_row)
    return {
        "can_write": can_write,
        "can_edit": editable and can_write,
        "can_repeat": can_repeat,
        "can_duplicate": editable and can_write and etype == "Sale",
        "can_void": can_write,
    }


def _txh_bind_action_buttons(
    action_cols,
    session,
    *,
    row_key: str,
    etype: str,
    eobj,
    defs: dict[str, bool],
) -> None:
    """Wire View / Edit / Repeat|Duplicate / Void callbacks into pre-built columns."""
    c_v, c_e, c_d, c_vd = action_cols
    if c_v.button(TXH_ACTION_VIEW, key=f"txh_v_{row_key}", help=_t("txh.view_help")):
        st.session_state["txh_active_view"] = None if st.session_state.get("txh_active_view") == row_key else row_key
        st.session_state["txh_active_edit"] = None
        st.rerun()
    if c_e.button(TXH_ACTION_EDIT, key=f"txh_e_{row_key}", help=_t("txh.edit_help"), disabled=not defs["can_edit"]):
        if st.session_state.get("txh_active_edit") == row_key:
            st.session_state["txh_active_edit"] = None
        else:
            for _sfx in ["date", "amt", "pm", "cust", "notes", "cat", "sub", "vendor"]:
                st.session_state.pop(f"edit_{_sfx}_{row_key}", None)
            st.session_state["txh_active_edit"] = row_key
            st.session_state["txh_active_view"] = None
        st.rerun()
    if defs["can_repeat"]:
        if c_d.button(TXH_ACTION_REPEAT, key=f"txh_r_{row_key}", help=_t("txh.repeat_help")):
            if _txh_apply_repeat_prefill(session, etype, eobj):
                st.session_state["txh_active_view"] = None
                st.session_state["txh_active_edit"] = None
                st.rerun()
    elif c_d.button(TXH_ACTION_DUPLICATE, key=f"txh_d_{row_key}", help=_t("txh.duplicate_help"), disabled=not defs["can_duplicate"]):
        _TYPE_IDX = {"Sale": 0, "ExpenseRecord": 1, "Purchase": 2}
        st.session_state["at_type_idx"] = _TYPE_IDX.get(etype, 0)
        st.session_state["at_amount_display"] = str(eobj.amount)
        st.session_state["at_notes_field"] = eobj.description or ""
        if etype == "Sale":
            st.session_state["at_pm"] = eobj.sale_type
            st.session_state["at_cust"] = eobj.customer_name if eobj.sale_type == "Credit" else ""
        elif etype == "ExpenseRecord":
            st.session_state["at_pm"] = eobj.payment_method or "Cash"
        elif etype == "Purchase":
            st.session_state["at_pm"] = eobj.purchase_type or "Credit"
        st.session_state["nav_selection"] = NAV_NEW_TRANSACTION
        st.rerun()
    if c_vd.button(TXH_ACTION_VOID, key=f"txh_vd_{row_key}", help=_t("txh.void_help"), disabled=not defs["can_void"]):
        st.session_state[f"txh_void_confirm_{row_key}"] = True
        st.rerun()


def _txh_render_mobile_actions(
    session, row_key: str, etype: str, eobj, *, is_void_row: bool
) -> None:
    """Mobile-only full-width action bar (txh_actions_* keys + mobile CSS)."""
    if is_void_row:
        return
    defs = _txh_action_defs(etype, eobj, is_void_row=is_void_row)
    with st.container(border=False, key=f"txh_actions_{row_key}"):
        _txh_bind_action_buttons(
            st.columns(4), session, row_key=row_key, etype=etype, eobj=eobj, defs=defs
        )


def _txh_render_desktop_actions(
    session,
    action_parent,
    row_key: str,
    etype: str,
    eobj,
    *,
    is_void_row: bool,
) -> None:
    """Desktop-only compact action group in Actions column (txh_dt_actions_* keys)."""
    if is_void_row:
        return
    defs = _txh_action_defs(etype, eobj, is_void_row=is_void_row)
    with action_parent:
        with st.container(border=False, key=f"txh_dt_actions_{row_key}"):
            _txh_bind_action_buttons(
                st.columns(4), session, row_key=row_key, etype=etype, eobj=eobj, defs=defs
            )


def _txh_je_amount_cell(amount: float) -> str:
    if amount and abs(amount) > 0.0001:
        return html.escape(f"{amount:,.2f}")
    return "—"


def _txh_render_view_je_block(session, journal_entries: list) -> None:
    """TXH-DETAIL-01 — Journal Entries grid in expanded view panel."""
    st.markdown(f"**{_t('je.journal_entries')}**")
    if not journal_entries:
        st.caption(_t("je.no_entries"))
        return
    for _je in journal_entries:
        _head = html.escape(f"{_je.entry_date} — {_je.description}")
        st.markdown(f'<div class="erp-txh-je-head">{_head}</div>', unsafe_allow_html=True)
        _rows = [
            '<div class="erp-txh-je-grid">',
            '<div class="erp-txh-je-line erp-txh-je-line--hdr">',
            f'<span class="erp-txh-je-account">{html.escape(_t("je.account"))}</span>',
            '<span class="erp-txh-je-dr">Dr</span>',
            '<span class="erp-txh-je-cr">Cr</span>',
            "</div>",
        ]
        for _ln in _je.lines:
            _ac = session.get(ChartOfAccounts, _ln.account_id)
            _aname = html.escape(_ac.account_name if _ac else f"Acct#{_ln.account_id}")
            _rows.extend([
                '<div class="erp-txh-je-line">',
                f'<span class="erp-txh-je-account">{_aname}</span>',
                f'<span class="erp-txh-je-dr">{_txh_je_amount_cell(_ln.debit)}</span>',
                f'<span class="erp-txh-je-cr">{_txh_je_amount_cell(_ln.credit)}</span>',
                "</div>",
            ])
        _rows.append("</div>")
        st.markdown("".join(_rows), unsafe_allow_html=True)


def _txh_render_view_edit_history_block(edit_logs: list) -> None:
    """TXH-DETAIL-01 — Edit History in expanded view panel."""
    if not edit_logs:
        return
    st.divider()
    st.markdown(f"**{_t('je.edit_history')}**")
    for _log in edit_logs:
        _ts = _log.timestamp.strftime("%d %b %Y %H:%M") if _log.timestamp else "—"
        try:
            _d = json.loads(_log.description or "{}")
            _usr = _d.get("user", "—")
            _bef = _d.get("before", {})
            _aft = _d.get("after", {})
        except Exception:
            _usr, _bef, _aft = "—", {}, {}
        _head = html.escape(f"{_ts} — {_usr}")
        st.markdown(f'<div class="erp-txh-edit-head">{_head}</div>', unsafe_allow_html=True)
        for _fld, _old in _bef.items():
            _old_s = html.escape(str(_old))
            _new_s = html.escape(str(_aft.get(_fld, "—")))
            _fld_s = html.escape(str(_fld))
            st.markdown(
                f'<div class="erp-txh-edit-line">'
                f'{_fld_s}: <span class="erp-txh-edit-old">{_old_s}</span>'
                f' → <span class="erp-txh-edit-new">{_new_s}</span>'
                f"</div>",
                unsafe_allow_html=True,
            )


def _txh_render_row_panels(
    session,
    *,
    row_key: str,
    etype: str,
    eobj,
    currency: str,
    cat_names_lkp: dict,
    subcat_names_lkp: dict,
    vendors: list,
) -> None:
    """Shared View / Edit / Void expand panels (accounting behavior unchanged)."""
    eid = eobj.id

    # ── View panel ────────────────────────────────────────────────────────
    if st.session_state.get("txh_active_view") == row_key:
        with st.container(border=True):
            _vh, _vc = st.columns([7, 1])
            _vh.markdown(f"**{_t('field.transaction_detail')}**")
            if _vc.button(_t("field.close"), key=f"txh_vclose_{row_key}"):
                st.session_state["txh_active_view"] = None
                st.rerun()
            _f1, _f2 = st.columns(2)
            if etype == "Sale":
                _f1.write(f"**Date:** {eobj.date}")
                _f2.write(f"**Amount:** {currency} {eobj.amount:,.2f}")
                _f1.write(f"**{_t('field.type')}:** {_t('field.sale_suffix', type=_i18n_db(SALE_TYPE_I18N, eobj.sale_type))}")
                _f2.write(f"**{_t('field.status')}:** {_i18n_db(SALE_STATUS_I18N, eobj.status)}")
                _f1.write(f"**{_t('field.reference')}:** {eobj.invoice_number}")
                _f2.write(f"**{_t('field.payment')}:** {_i18n_db(SALE_TYPE_I18N, eobj.sale_type)}")
                _f1.write(f"**{_t('field.customer')}:** {eobj.customer_name}")
                if eobj.sale_type == "Credit":
                    _f2.write(f"**{_t('field.due_date')}:** {eobj.due_date}")
                st.write(f"**{_t('field.notes')}:** {eobj.description or '—'}")
                if eobj.sale_type in ("Credit", "Card", "Cash"):
                    try:
                        _settings = load_settings()
                        _pdf_bytes = generate_invoice_pdf(
                            invoice_number=eobj.invoice_number,
                            invoice_date=eobj.date,
                            due_date=eobj.due_date or eobj.date,
                            customer_name=eobj.customer_name,
                            description=eobj.description or "",
                            amount=eobj.amount,
                            paid_amount=eobj.paid_amount or 0.0,
                            status=eobj.status,
                            currency=_settings.get("currency", "TRY"),
                            company_name=_settings.get("company_name", "My Company"),
                        )
                        st.download_button(
                            label=_t("field.download_invoice"),
                            data=_pdf_bytes,
                            file_name=f"{eobj.invoice_number}.pdf",
                            mime="application/pdf",
                            key=f"dl_inv_{eobj.id}",
                        )
                    except Exception:
                        pass
                _ref_types = ["CashSale", "CardSale", "CreditSale", "ReceivablePayment"]
            elif etype == "ExpenseRecord":
                _f1.write(f"**{_t('field.date')}:** {eobj.date}")
                _f2.write(f"**{_t('field.amount')}:** {currency} {eobj.amount:,.2f}")
                _f1.write(f"**{_t('field.type')}:** {eobj.expense_type}")
                _f2.write(f"**{_t('field.payment')}:** {_i18n_db(PAYMENT_METHOD_I18N, eobj.payment_method) if eobj.payment_method else '—'}")
                _f1.write(f"**{_t('field.category')}:** {cat_names_lkp.get(eobj.tx_category_id, eobj.category or '—')}")
                _f2.write(f"**{_t('field.subcategory')}:** {subcat_names_lkp.get(eobj.tx_subcategory_id, '—')}")
                st.write(f"**{_t('field.notes')}:** {eobj.description or '—'}")
                _ref_types = ["Expense"]
            elif etype == "Purchase":
                _pv = session.get(Vendor, eobj.vendor_id)
                _f1.write(f"**{_t('field.date')}:** {eobj.date}")
                _f2.write(f"**{_t('field.amount')}:** {currency} {eobj.amount:,.2f}")
                _f1.write(f"**{_t('field.vendor')}:** {_pv.name if _pv else '—'}")
                _f2.write(f"**{_t('field.type')}:** {eobj.purchase_type}")
                _f1.write(f"**{_t('field.category')}:** {cat_names_lkp.get(eobj.tx_category_id, eobj.gl_debit or '—')}")
                _f2.write(f"**{_t('field.subcategory')}:** {subcat_names_lkp.get(eobj.tx_subcategory_id, '—')}")
                st.write(f"**{_t('field.notes')}:** {eobj.description or '—'}")
                _ref_types = ["Purchase", "CashPurchase", "BankPurchase"]
            elif etype == "BankTransaction":
                _ba = session.get(BankAccount, eobj.account_id)
                _f1.write(f"**{_t('field.date')}:** {eobj.date}")
                _f2.write(f"**{_t('field.amount')}:** {currency} {eobj.amount:,.2f}")
                _f1.write(f"**{_t('field.account')}:** {_ba.name if _ba else '—'}")
                _f2.write(f"**{_t('field.type')}:** {_i18n_db(BANK_TXN_TYPE_I18N, eobj.type)}")
                st.write(f"**{_t('field.description')}:** {eobj.description or '—'}")
                _ref_types = ["BankDeposit", "BankWithdrawal", "BankTransfer"]
            elif etype == "Payable":
                _pav = session.get(Vendor, eobj.vendor_id)
                _f1.write(f"**{_t('field.date')}:** {eobj.date}")
                _f2.write(f"**{_t('field.amount')}:** {currency} {eobj.amount:,.2f}")
                _f1.write(f"**{_t('field.vendor')}:** {_pav.name if _pav else '—'}")
                _f2.write(f"**{_t('field.due_date')}:** {eobj.due_date}")
                _f1.write(f"**{_t('field.status')}:** {_t('field.paid') if eobj.paid else _t('field.open')}")
                _f2.write(f"**{_t('field.method')}:** {_i18n_db(PAYMENT_METHOD_I18N, eobj.payment_method) if eobj.payment_method else '—'}")
                st.write(f"**{_t('field.description')}:** {eobj.description or '—'}")
                _ref_types = ["PayableCreation", "PayablePayment"]
            else:
                _ref_types = []

            st.divider()
            _direct_je = cq(session, JournalEntry).filter(
                JournalEntry.reference_type.in_(_ref_types),
                JournalEntry.reference_id == eid,
            ).order_by(JournalEntry.entry_date).all() if _ref_types else []
            _reversal_je = cq(session, JournalEntry).filter(
                JournalEntry.reference_type == "Reversal",
                JournalEntry.reference_id.in_([_je.id for _je in _direct_je]),
            ).order_by(JournalEntry.entry_date).all() if _direct_je else []
            _all_je = sorted(_direct_je + _reversal_je, key=lambda _e: _e.entry_date)
            _txh_render_view_je_block(session, _all_je)

            _edit_logs = (
                cq(session, AuditLog)
                .filter_by(action="Edit", entity_type=etype, entity_id=eid)
                .order_by(AuditLog.timestamp.desc())
                .all()
            )
            _txh_render_view_edit_history_block(_edit_logs)

    elif st.session_state.get("txh_active_edit") == row_key:
        with st.container(border=True):
            _eh, _ec = st.columns([7, 1])
            _edit_title = eobj.invoice_number if etype == "Sale" else f"{etype.replace('Record','')} #{eid}"
            _eh.markdown(f"**{_t('field.edit_title', title=_edit_title)}**")
            if _ec.button("✕", key=f"txh_eclose_{row_key}", help=_t("field.cancel_edit_help")):
                st.session_state["txh_active_edit"] = None
                st.rerun()
            st.warning(_t("field.edit_warning"))

            if etype == "Sale":
                _ef1, _ef2 = st.columns(2)
                _new_date = _ef1.date_input(_t("col.date"), value=eobj.date, key=f"edit_date_{row_key}")
                _new_amt = amount_input(_t("col.amount"), key=f"edit_amt_{row_key}", default=eobj.amount, container=_ef2)
                _ef3, _ef4 = st.columns(2)
                _pm_opts = ["Cash", "Card", "Credit"]
                _new_pm = _ef3.selectbox(_t("form.payment_method"), _pm_opts,
                                          index=_pm_opts.index(eobj.sale_type) if eobj.sale_type in _pm_opts else 0,
                                          format_func=lambda v: _i18n_db(PAYMENT_METHOD_I18N, v),
                                          key=f"edit_pm_{row_key}")
                _new_cust = _ef4.text_input(_t("form.customer"), value=eobj.customer_name,
                                             key=f"edit_cust_{row_key}", disabled=(_new_pm != "Credit"))
                _new_notes = st.text_area(_t("form.notes"), value=eobj.description or "", key=f"edit_notes_{row_key}")
                if st.button(_t("form.save_changes"), key=f"edit_save_{row_key}", type="primary"):
                    if not _new_amt or _new_amt <= 0:
                        st.error(_t("form.invalid_amount"))
                    else:
                        _f = {}
                        if _new_date != eobj.date: _f["date"] = _new_date
                        if abs(_new_amt - eobj.amount) > 0.001: _f["amount"] = _new_amt
                        if _new_pm != eobj.sale_type: _f["sale_type"] = _new_pm
                        if _new_pm == "Credit" and _new_cust.strip() != eobj.customer_name:
                            _f["customer_name"] = _new_cust.strip()
                        if _new_notes.strip() != (eobj.description or ""): _f["description"] = _new_notes.strip()
                        if not _f:
                            st.info(_t("je.no_changes"))
                        else:
                            _ok, _err = edit_sale(session, eid, _f)
                            if _ok:
                                st.session_state["txh_active_edit"] = None
                                st.rerun()
                            else:
                                st.error(_err)

            elif etype == "ExpenseRecord":
                _ef1, _ef2 = st.columns(2)
                _new_date = _ef1.date_input(_t("col.date"), value=eobj.date, key=f"edit_date_{row_key}")
                _new_amt = amount_input(_t("col.amount"), key=f"edit_amt_{row_key}", default=eobj.amount, container=_ef2)
                _epm_opts = _business_pay_methods(session)
                _new_pm = st.selectbox(_t("form.payment_method"), _epm_opts,
                                        index=_epm_opts.index(eobj.payment_method) if eobj.payment_method in _epm_opts else 0,
                                        format_func=lambda v: _i18n_db(PAYMENT_METHOD_I18N, v),
                                        key=f"edit_pm_{row_key}")
                _ecats = cq(session, TransactionCategory).filter_by(transaction_type="Expense", is_active=True).order_by(TransactionCategory.name).all()
                _ecat_names = [c.name for c in _ecats]
                _curr_cat = cat_names_lkp.get(eobj.tx_category_id, eobj.category or "")
                _new_cat_name = st.selectbox(_t("form.category"), _ecat_names,
                                              index=_ecat_names.index(_curr_cat) if _curr_cat in _ecat_names else 0,
                                              key=f"edit_cat_{row_key}") if _ecat_names else None
                _new_cat_obj = next((c for c in _ecats if c.name == _new_cat_name), None) if _new_cat_name else None
                _new_subcat_id = eobj.tx_subcategory_id
                if _new_cat_obj:
                    _esubs = cq(session, TransactionSubcategory).filter_by(category_id=_new_cat_obj.id, is_active=True).order_by(TransactionSubcategory.name).all()
                    _esub_names = [s.name for s in _esubs]
                    _curr_sub = subcat_names_lkp.get(eobj.tx_subcategory_id, "")
                    if _esub_names:
                        _new_sub_name = st.selectbox(_t("form.subcategory"), _esub_names,
                                                      index=_esub_names.index(_curr_sub) if _curr_sub in _esub_names else 0,
                                                      key=f"edit_sub_{row_key}")
                        _sub_obj = next((s for s in _esubs if s.name == _new_sub_name), None)
                        _new_subcat_id = _sub_obj.id if _sub_obj else None
                _new_notes = st.text_area(_t("form.notes"), value=eobj.description or "", key=f"edit_notes_{row_key}")
                if st.button(_t("form.save_changes"), key=f"edit_save_{row_key}", type="primary"):
                    if not _new_amt or _new_amt <= 0:
                        st.error(_t("form.invalid_amount"))
                    else:
                        _f = {}
                        if _new_date != eobj.date: _f["date"] = _new_date
                        if abs(_new_amt - eobj.amount) > 0.001: _f["amount"] = _new_amt
                        if _new_pm != (eobj.payment_method or "Cash"): _f["payment_method"] = _new_pm
                        if _new_cat_obj and _new_cat_obj.id != eobj.tx_category_id:
                            _f["tx_category_id"] = _new_cat_obj.id
                            _f["expense_type"] = _new_cat_name
                            _f["category"] = _new_cat_name
                        if _new_subcat_id != eobj.tx_subcategory_id: _f["tx_subcategory_id"] = _new_subcat_id
                        if _new_notes.strip() != (eobj.description or ""): _f["description"] = _new_notes.strip()
                        if not _f:
                            st.info(_t("je.no_changes"))
                        else:
                            _ok, _err = edit_expense(session, eid, _f)
                            if _ok:
                                st.session_state["txh_active_edit"] = None
                                st.rerun()
                            else:
                                st.error(_err)

            elif etype == "Purchase":
                _ef1, _ef2 = st.columns(2)
                _new_date = _ef1.date_input(_t("col.date"), value=eobj.date, key=f"edit_date_{row_key}")
                _new_amt = amount_input(_t("col.amount"), key=f"edit_amt_{row_key}", default=eobj.amount, container=_ef2)
                _vnames = [v.name for v in _vendors]
                _cv = session.get(Vendor, eobj.vendor_id)
                _cvname = _cv.name if _cv else ""
                _new_vname = st.selectbox(_t("form.vendor"), _vnames,
                                           index=_vnames.index(_cvname) if _cvname in _vnames else 0,
                                           key=f"edit_vendor_{row_key}") if _vnames else None
                _new_vendor = next((v for v in _vendors if v.name == _new_vname), None) if _new_vname else None
                _pt_opts = _at_purchase_pay_methods(session)
                _new_pt = st.selectbox(_t("form.purchase_type"), _pt_opts,
                                        index=_pt_opts.index(eobj.purchase_type) if eobj.purchase_type in _pt_opts else 0,
                                        key=f"edit_pm_{row_key}")
                _pcats = cq(session, TransactionCategory).filter_by(transaction_type="Purchase", is_active=True).order_by(TransactionCategory.name).all()
                _pcat_names = [c.name for c in _pcats]
                _curr_pcat = cat_names_lkp.get(eobj.tx_category_id, eobj.gl_debit or "")
                _new_pcat_name = st.selectbox(_t("form.category"), _pcat_names,
                                               index=_pcat_names.index(_curr_pcat) if _curr_pcat in _pcat_names else 0,
                                               key=f"edit_cat_{row_key}") if _pcat_names else None
                _new_pcat_obj = next((c for c in _pcats if c.name == _new_pcat_name), None) if _new_pcat_name else None
                _new_psubcat_id = eobj.tx_subcategory_id
                if _new_pcat_obj:
                    _psubs = cq(session, TransactionSubcategory).filter_by(category_id=_new_pcat_obj.id, is_active=True).order_by(TransactionSubcategory.name).all()
                    _psub_names = [s.name for s in _psubs]
                    _curr_psub = subcat_names_lkp.get(eobj.tx_subcategory_id, "")
                    if _psub_names:
                        _new_psub_name = st.selectbox(_t("form.subcategory"), _psub_names,
                                                       index=_psub_names.index(_curr_psub) if _curr_psub in _psub_names else 0,
                                                       key=f"edit_sub_{row_key}")
                        _psub_obj = next((s for s in _psubs if s.name == _new_psub_name), None)
                        _new_psubcat_id = _psub_obj.id if _psub_obj else None
                _new_notes = st.text_area(_t("form.notes"), value=eobj.description or "", key=f"edit_notes_{row_key}")
                if st.button(_t("form.save_changes"), key=f"edit_save_{row_key}", type="primary"):
                    if not _new_amt or _new_amt <= 0:
                        st.error(_t("form.invalid_amount"))
                    else:
                        _f = {}
                        if _new_date != eobj.date: _f["date"] = _new_date
                        if abs(_new_amt - eobj.amount) > 0.001: _f["amount"] = _new_amt
                        if _new_vendor and _new_vendor.id != eobj.vendor_id: _f["vendor_id"] = _new_vendor.id
                        if _new_pt != (eobj.purchase_type or "Credit"): _f["purchase_type"] = _new_pt
                        if _new_pcat_obj and _new_pcat_obj.id != eobj.tx_category_id:
                            _f["tx_category_id"] = _new_pcat_obj.id
                            _f["gl_debit"] = _new_pcat_name
                        if _new_psubcat_id != eobj.tx_subcategory_id: _f["tx_subcategory_id"] = _new_psubcat_id
                        if _new_notes.strip() != (eobj.description or ""): _f["description"] = _new_notes.strip()
                        if not _f:
                            st.info(_t("je.no_changes"))
                        else:
                            _ok, _err = edit_purchase(session, eid, _f)
                            if _ok:
                                st.session_state["txh_active_edit"] = None
                                st.rerun()
                            else:
                                st.error(_err)
            else:
                st.info(_t("je.unsupported_type"))

    if st.session_state.get(f"txh_void_confirm_{row_key}"):
        with st.container(border=True):
            st.warning(_t("je.void_confirm"))
            _vr = st.text_input(_t("form.void_reason_label"), key=f"txh_void_reason_{row_key}", placeholder=_t("field.void_reason_placeholder"))
            _vc1, _vc2 = st.columns(2)
            if _vc1.button("Confirm Void", key=f"txh_void_ok_{row_key}", type="primary"):
                _reason = _vr or "Manual void"
                if etype == "Sale":
                    void_sale(session, eid, _reason)
                elif etype == "ExpenseRecord":
                    void_expense(session, eid, _reason)
                elif etype == "Purchase":
                    void_purchase(session, eid, _reason)
                elif etype == "BankTransaction":
                    _btxn_chk = session.get(BankTransaction, eid)
                    _desc_chk  = (_btxn_chk.description or "") if _btxn_chk else ""
                    if _btxn_chk and _desc_chk.startswith("Card Sale "):
                        st.error(
                            "This banking entry originated from a Card Sale. "
                            "Card Sale deposits cannot be voided from Banking. "
                            "Void the originating Sale instead."
                        )
                    elif _btxn_chk and (
                        _desc_chk.startswith("Capital Contribution #")
                        or _desc_chk.startswith("Owner Drawing #")
                    ):
                        st.error(_t("bank.err.equity_void"))
                    elif _btxn_chk and (_btxn_chk.statement_ref or "").startswith("bsr:"):
                        st.error(_t("bank.err.stmt_linked_void"))
                    else:
                        void_bank_transaction(session, eid, _reason)
                elif etype == "Payable":
                    void_payable(session, eid, _reason)
                st.session_state.pop(f"txh_void_confirm_{row_key}", None)
                st.rerun()
            if _vc2.button("Cancel", key=f"txh_void_cancel_{row_key}"):
                st.session_state.pop(f"txh_void_confirm_{row_key}", None)
                st.rerun()


def _txh_render_mobile_card(
    row_dict: dict,
    *,
    row_key: str,
    is_void_row: bool,
    is_corrected: bool,
) -> None:
    """Mobile-only card presentation."""
    with st.container(border=False, key=f"txh_info_{row_key}"):
        txn_type_key = str(row_dict.get("Type", ""))
        icon = _TXH_TYPE_ICON.get(txn_type_key, "📄")
        icon_cls = _txh_row_icon_class(txn_type_key)
        txn_type_disp = _localize_txn_type(txn_type_key)
        status = str(row_dict.get("Status", ""))
        status_disp = _localize_txn_status(status)
        amt = float(row_dict.get("Amount", 0))
        is_in = txn_type_key in _TXH_INFLOW_TYPES
        amt_cls = (
            "erp-txh-row-amt--muted"
            if is_void_row
            else ("erp-txh-row-amt--in" if is_in else "erp-txh-row-amt--out")
        )
        amt_sign = "+" if is_in else "−"
        date_str = str(row_dict.get("Date", ""))[:10]
        party = html.escape(str(row_dict.get("Party", "")))
        ref = html.escape(str(row_dict.get("Reference", "")))
        curr = html.escape(str(row_dict.get("Currency", "")))
        status_pills = _txh_status_pills_html(
            status, status_disp, is_corrected=is_corrected, is_void_row=is_void_row,
        )
        void_cls = " erp-txh-row--void" if is_void_row else ""
        st.markdown(
            f'<div class="erp-txh-row{void_cls}">'
            f'<div class="{icon_cls}">{icon}</div>'
            f'<div class="erp-txh-row-main">'
            f'<div class="erp-txh-row-amt {amt_cls}">'
            f'{amt_sign}{curr} {amt:,.2f}</div>'
            f'<div class="erp-txh-row-type">{html.escape(txn_type_disp)}</div>'
            f'<div class="erp-txh-row-party">{party or "—"}</div>'
            f'<div class="erp-txh-row-meta">'
            f'<span class="erp-txh-row-ref">{ref}</span>'
            f'{status_pills}'
            f'<span class="erp-txh-row-date">{date_str}</span>'
            f'</div></div></div>',
            unsafe_allow_html=True,
        )


def _txh_render_desktop_table_header() -> None:
    st.markdown(
        '<div class="erp-txh-dt-shell">'
        f'<div class="erp-txh-dt-head">'
        f'<span>{html.escape(_t("col.date"))}</span>'
        f'<span>{html.escape(_t("col.type"))}</span>'
        f'<span>{html.escape(_t("col.party"))}</span>'
        f'<span>{html.escape(_t("col.description"))}</span>'
        f'<span class="erp-txh-dt-head-amt">{html.escape(_t("col.amount"))}</span>'
        f'<span>{html.escape(_t("field.status"))}</span>'
        f'<span>{html.escape(_t("col.actions"))}</span>'
        f'</div><div class="erp-txh-dt-wrap">',
        unsafe_allow_html=True,
    )


def _txh_render_desktop_row(
    session,
    row_dict: dict,
    etype: str,
    eobj,
    *,
    row_key: str,
    is_void_row: bool,
    is_corrected: bool,
) -> None:
    """Desktop-only table row presentation."""
    txn_type_key = str(row_dict.get("Type", ""))
    txn_type_disp = _localize_txn_type(txn_type_key)
    status = str(row_dict.get("Status", ""))
    status_disp = _localize_txn_status(status)
    amt = float(row_dict.get("Amount", 0))
    is_in = txn_type_key in _TXH_INFLOW_TYPES
    amt_cls = (
        "erp-txh-dt-cell--amt-muted"
        if is_void_row
        else ("erp-txh-dt-cell--amt-in" if is_in else "erp-txh-dt-cell--amt-out")
    )
    amt_sign = "+" if is_in else "−"
    date_str = str(row_dict.get("Date", ""))[:10]
    party = html.escape(str(row_dict.get("Party", "") or "—"))
    desc = html.escape(_txh_truncate_text(str(row_dict.get("Description", ""))))
    curr = html.escape(str(row_dict.get("Currency", "")))
    void_cls = " erp-txh-dt-cell--void" if is_void_row else ""
    status_html = _txh_status_pills_html(status, status_disp, is_corrected=is_corrected, is_void_row=is_void_row)

    with st.container(border=False, key=f"txh_dt_row_{row_key}"):
        c_date, c_type, c_party, c_desc, c_amt, c_status, c_act = st.columns(
            _TXH_DESKTOP_COL_WEIGHTS
        )
        c_date.markdown(
            f'<div class="erp-txh-dt-cell{void_cls}">{html.escape(date_str)}</div>',
            unsafe_allow_html=True,
        )
        c_type.markdown(
            f'<div class="erp-txh-dt-cell{void_cls}">{html.escape(txn_type_disp)}</div>',
            unsafe_allow_html=True,
        )
        c_party.markdown(
            f'<div class="erp-txh-dt-cell{void_cls}" title="{party}">{party}</div>',
            unsafe_allow_html=True,
        )
        c_desc.markdown(
            f'<div class="erp-txh-dt-cell erp-txh-dt-cell--desc{void_cls}" title="{desc}">{desc or "—"}</div>',
            unsafe_allow_html=True,
        )
        c_amt.markdown(
            f'<div class="erp-txh-dt-cell erp-txh-dt-cell--amt {amt_cls}{void_cls}">'
            f'{amt_sign}{curr}\u00a0{amt:,.2f}</div>',
            unsafe_allow_html=True,
        )
        c_status.markdown(
            f'<div class="erp-txh-dt-cell erp-txh-dt-cell--status{void_cls}">{status_html}</div>',
            unsafe_allow_html=True,
        )
        if not is_void_row:
            _txh_render_desktop_actions(
                session, c_act, row_key, etype, eobj, is_void_row=is_void_row,
            )


def _txh_render_transaction_list(
    session,
    *,
    rows: list[tuple[dict, str, object]],
    edit_pairs: set[tuple[str, int]],
    currency: str,
    cat_names_lkp: dict,
    subcat_names_lkp: dict,
    vendors: list,
    mobile: bool,
) -> None:
    if not mobile:
        _txh_render_desktop_table_header()

    for row_dict, etype, eobj in rows:
        eid = eobj.id
        row_key = f"{etype}_{eid}"
        is_void_row = getattr(eobj, "is_void", False)
        is_corrected = (etype, eid) in edit_pairs

        if mobile:
            with st.container(border=False, key=f"txh_row_{row_key}"):
                _txh_render_mobile_card(
                    row_dict,
                    row_key=row_key,
                    is_void_row=is_void_row,
                    is_corrected=is_corrected,
                )
                _txh_render_mobile_actions(
                    session, row_key, etype, eobj, is_void_row=is_void_row
                )
                _txh_render_row_panels(
                    session,
                    row_key=row_key,
                    etype=etype,
                    eobj=eobj,
                    currency=currency,
                    cat_names_lkp=cat_names_lkp,
                    subcat_names_lkp=subcat_names_lkp,
                    vendors=vendors,
                )
        else:
            _txh_render_desktop_row(
                session, row_dict, etype, eobj,
                row_key=row_key,
                is_void_row=is_void_row,
                is_corrected=is_corrected,
            )
            _txh_render_row_panels(
                session,
                row_key=row_key,
                etype=etype,
                eobj=eobj,
                currency=currency,
                cat_names_lkp=cat_names_lkp,
                subcat_names_lkp=subcat_names_lkp,
                vendors=vendors,
            )

    if not mobile:
        st.markdown("</div></div>", unsafe_allow_html=True)


def render_transaction_history(session):
    settings = load_settings()
    currency = settings.get("currency", "USD")
    cat_names_lkp, subcat_names_lkp = _load_cat_lookup(session)
    user_lkp = _load_user_lookup(session)  # Step 6.4: {user_id: display_name}

    _txh_mobile = _sync_mobile_ui_flag_from_cookie()
    if _txh_mobile:
        st.markdown('<div class="erp-txh-mobile-host"></div>', unsafe_allow_html=True)
    else:
        st.markdown('<div class="erp-txh-desktop-host"></div>', unsafe_allow_html=True)
    st.markdown(
        section_header_html(_t("txn.page_banner")),
        unsafe_allow_html=True,
    )

    # ── Filter card ────────────────────────────────────────────────────────────
    with st.container(border=True, key="txh_filters_card"):
        st.markdown(
            mobile_section_label_html(_t("txn.filters_label")),
            unsafe_allow_html=True,
        )
        with st.container(border=False, key="txh_filter_search"):
            st.text_input(
                _t("search.table_label"),
                placeholder=_t("txn.search_ph"),
                key="txh_search",
            )
            if _txh_search_keyword():
                st.caption(_t("search.scope.txn_history"))
        with st.container(border=False, key="txh_filter_dates"):
            start_date, end_date = _render_txh_date_filters(st)
        with st.container(border=False, key="txh_filter_row1"):
            fc1, fc2 = st.columns(2)
            _txh_all = _t("form.all")
            keyword = _txh_search_keyword()
            type_filter = fc1.selectbox(
                _t("col.type"),
                [_txh_all, "Sale", "Expense", "Purchase", NAV_BANKING, "Payable"],
                format_func=lambda v: v if v == _txh_all else _i18n_db(_TXH_TYPE_FILTER_I18N, v),
                key="txh_type",
            )
            method_filter = fc2.selectbox(
                _t("txn.method_filter"),
                [_txh_all, "Cash", "Bank", "Credit", "Mobile Money"],
                format_func=lambda v: _i18n_db(PAYMENT_METHOD_I18N, v),
                key="txh_method",
            )

        # Category / Subcategory inside the filter card
        with st.container(border=False, key="txh_filter_row2"):
            col6, col7 = st.columns(2)
            _cat_type_map = {"Sale": "Sale", "Expense": "Expense", "Purchase": "Purchase"}
            _cat_filter_type = _cat_type_map.get(type_filter)
            if _cat_filter_type:
                _avail_cats = (
                    cq(session, TransactionCategory)
                    .filter_by(transaction_type=_cat_filter_type, is_active=True)
                    .order_by(TransactionCategory.name)
                    .all()
                )
            else:
                _avail_cats = (
                    cq(session, TransactionCategory)
                    .filter_by(is_active=True)
                    .order_by(TransactionCategory.name)
                    .all()
                )
            cat_filter = col6.selectbox(
                _t("form.category"), [_txh_all] + [c.name for c in _avail_cats], key="txh_cat"
            )
            if cat_filter != _txh_all:
                _sel_cat = next((c for c in _avail_cats if c.name == cat_filter), None)
                _avail_subcats = (
                    cq(session, TransactionSubcategory)
                    .filter_by(category_id=_sel_cat.id, is_active=True)
                    .order_by(TransactionSubcategory.name)
                    .all()
                ) if _sel_cat else []
                subcat_filter = col7.selectbox(
                    _t("form.subcategory"), [_txh_all] + [s.name for s in _avail_subcats], key="txh_subcat"
                )
            else:
                subcat_filter = _txh_all

    show_voided = st.checkbox(_t("txn.show_voided"), value=False, key="txh_show_void")

    rows = _txh_fetch_filtered_rows(
        session,
        start_date=start_date,
        end_date=end_date,
        keyword=keyword,
        type_filter=type_filter,
        method_filter=method_filter,
        cat_filter=cat_filter,
        subcat_filter=subcat_filter,
        show_voided=show_voided,
        currency=currency,
        cat_names_lkp=cat_names_lkp,
        subcat_names_lkp=subcat_names_lkp,
        user_lkp=user_lkp,
        txh_all=_txh_all,
    )
    df = _txh_rows_to_dataframe(rows)

    # ── Result header + export ──────────────────────────────────────────────────
    with st.container(border=False, key="txh_result_hdr"):
        result_c1, result_c2 = st.columns([3, 1])
        period_label = f"{start_date.strftime('%d %b')} – {end_date.strftime('%d %b %Y')}"
        result_c1.markdown(
            f'<div class="erp-txh-result-count">'
            f'{len(df)} transaction{"s" if len(df) != 1 else ""} '
            f'<span class="erp-txh-result-period">· {html.escape(period_label)}</span></div>',
            unsafe_allow_html=True,
        )
    if not df.empty:
        _df_export = df.copy()
        _df_export["Type"] = _df_export["Type"].map(_localize_txn_type)
        _df_export["Status"] = _df_export["Status"].map(_localize_txn_status)
        _df_export["Method"] = _df_export["Method"].map(
            lambda v: _i18n_db(PAYMENT_METHOD_I18N, v) if v else v
        )
        with result_c2:
            render_export_buttons(_localize_df(_df_export), "Transaction_History")

    if not rows:
        st.info(_t("search.no_results_table"))
        return

    # ── Pre-load corrected set (entity_type, entity_id pairs with Edit logs) ───
    _edit_pairs = {
        (r.entity_type, r.entity_id)
        for r in cq(session, AuditLog).filter_by(action="Edit").all()
    }

    if "txh_active_view" not in st.session_state:
        st.session_state["txh_active_view"] = None
    if "txh_active_edit" not in st.session_state:
        st.session_state["txh_active_edit"] = None

    _vendors = cq(session, Vendor).filter_by(is_active=True).order_by(Vendor.name).all()

    _txh_render_transaction_list(
        session,
        rows=rows,
        edit_pairs=_edit_pairs,
        currency=currency,
        cat_names_lkp=cat_names_lkp,
        subcat_names_lkp=subcat_names_lkp,
        vendors=_vendors,
        mobile=_txh_mobile,
    )


def _bsi_mapping_from_session() -> dict[str, str | None]:
    """Read column mapping from Streamlit widget session state."""
    out: dict[str, str | None] = {}
    for field in CANONICAL_FIELDS:
        picked = st.session_state.get(f"bsi_map_{field}", "—")
        out[field] = None if not picked or picked == "—" else picked
    return out


def _bsi_apply_header_row(row: int) -> None:
    """Set header row before number_input renders (on_click runs pre-widget)."""
    st.session_state["bsi_header_row"] = int(row)


def _bsi_render_delete_import(session, imp: BankStatementImport, company_id: int) -> None:
    """Two-step delete for a staged bank statement import."""
    if not _can("import_bank_statement"):
        return
    confirm_key = f"bsi_delete_confirm_{imp.id}"
    if st.session_state.get(confirm_key):
        st.warning(
            _t(
                "banking.import.delete_confirm",
                id=imp.id,
                filename=imp.file_name,
                rows=imp.row_count,
            )
        )
        c1, c2 = st.columns(2)
        if c1.button(_t("banking.import.delete_btn"), key=f"bsi_delete_yes_{imp.id}", type="primary"):
            if delete_bank_statement_import(session, imp.id, company_id):
                log_audit(
                    session,
                    "Delete",
                    "BankStatementImport",
                    imp.id,
                    f"Deleted {imp.file_name} ({imp.row_count} rows)",
                )
                dup = st.session_state.get("bsi_dup_warning")
                if dup and getattr(dup, "id", None) == imp.id:
                    st.session_state.pop("bsi_dup_warning", None)
                st.session_state.pop("bsi_force_duplicate", None)
                st.session_state.pop(confirm_key, None)
                st.success(_t("banking.import.delete_ok", id=imp.id))
                st.rerun()
        if c2.button(_t("banking.import.delete_cancel"), key=f"bsi_delete_no_{imp.id}"):
            st.session_state.pop(confirm_key, None)
            st.rerun()
    elif st.button(_t("banking.import.delete_btn"), key=f"bsi_delete_{imp.id}"):
        st.session_state[confirm_key] = True
        st.rerun()


def _postable_deposit_rows(session, cid: int) -> list:
    """Staging bank statement credits ready for card-clearing match."""
    return [
        r
        for r in get_postable_rows(session, cid)
        if r.credit_amount and not r.debit_amount
    ]


def _bsi_statement_post_error_key(exc: Exception) -> tuple[str, dict]:
    """Map statement-post ValueError to a friendly locale key (BANKING-UX-03 P1.1)."""
    if not isinstance(exc, ValueError):
        raise exc
    raw = str(exc)
    if raw.startswith("Year ") and "is closed" in raw:
        return "banking.import.post_error.closed_year", {}
    if "Period '" in raw and "is closed" in raw:
        return "banking.import.post_error.closed_period", {}
    return "banking.import.post_error.blocked", {"detail": raw}


def _bsi_statement_post_error_message(exc: Exception) -> str:
    """Operator-facing text for statement post failures."""
    if isinstance(exc, MatchPostError):
        return str(exc)
    key, kwargs = _bsi_statement_post_error_key(exc)
    return _t(key, **kwargs)


def _bsi_render_statement_post_error(exc: Exception) -> None:
    st.error(_bsi_statement_post_error_message(exc))


def _bsi_review_skip_row_label(row: BankStatementRow) -> str:
    if row.credit_amount and not row.debit_amount:
        sign = "+"
    elif row.debit_amount and not row.credit_amount:
        sign = "-"
    else:
        sign = "·"
    return _t(
        "banking.import.review.skip_row_label",
        row=row.import_row_index,
        date=str(row.date) if row.date else "—",
        sign=sign,
        amount=f"{row.amount:,.2f}",
        description=(row.description or "")[:50],
    )


def _render_bsi_deposit_clearing_panel(session, sel_row, cid: int) -> None:
    """Line summary + card clearing match panel (single posting UI)."""
    _render_bsi_match_line_summary(sel_row)
    _render_bsi_deposit_clearing(session, sel_row, cid)


def _render_bsi_match_line_summary(sel_row) -> None:
    """Pinned summary for the selected statement line."""
    sign = "+" if sel_row.credit_amount else "-"
    flow_key = (
        "banking.import.match.deposit"
        if sel_row.credit_amount
        else "banking.import.match.withdrawal"
    )
    render_kpi_grid([
        {"label": _t("banking.import.match.line_date"), "value": str(sel_row.date or "—")},
        {"label": _t(flow_key), "value": f"{sign}{sel_row.amount:,.2f}"},
    ])
    st.text_area(
        _t("banking.import.match.line_description"),
        value=sel_row.description or "",
        disabled=True,
        height=68,
        key=f"bsi_line_desc_{sel_row.id}",
    )


def _bsi_deposit_kind_options(session) -> list[tuple[str, str]]:
    opts: list[tuple[str, str]] = []
    if _card_settlement_on(session):
        opts.append(("card_clearing", "banking.import.match.kind.card_clearing"))
    eq_key = (
        "banking.import.match.partner_loan_expander"
        if _has_active_partners(session)
        else "banking.import.match.owner_loan_expander"
    )
    opts.append(("equity_loan", eq_key))
    opts.append(("other_income", "banking.import.match.kind.other_income"))
    return opts


def _bsi_withdrawal_kind_options(session) -> list[tuple[str, str]]:
    opts: list[tuple[str, str]] = [
        ("vendor", "banking.import.match.kind.vendor"),
    ]
    if _has_active_workers(session):
        opts.append(("worker_payroll", "banking.import.match.kind.worker_payroll"))
    if _company_card_on(session):
        opts.append(("cc_bill", "banking.import.match.kind.cc_bill"))
    if _bank_charges_on(session):
        opts.append(("bank_fee", "banking.import.match.kind.bank_fee"))
    eq_key = (
        "banking.import.match.partner_loan_expander"
        if _has_active_partners(session)
        else "banking.import.match.owner_loan_expander"
    )
    opts.append(("equity_loan", eq_key))
    return opts


def _bsi_default_match_kind(session, sel_row, *, is_deposit: bool) -> str:
    desc = sel_row.description or ""
    if is_deposit:
        default = suggest_deposit_match_kind(
            desc,
            card_settlement_on=_card_settlement_on(session),
        )
        valid = {k for k, _ in _bsi_deposit_kind_options(session)}
        return default if default in valid else "other_income"
    default = suggest_withdrawal_match_kind(
        desc,
        company_card_on=_company_card_on(session),
        bank_charges_on=_bank_charges_on(session),
        has_workers=_has_active_workers(session),
    )
    valid = {k for k, _ in _bsi_withdrawal_kind_options(session)}
    return default if default in valid else "vendor"


def _bsi_widget_key(base: str, row_id: int) -> str:
    """Row-scoped Streamlit widget key for Match queue (prevents cross-row leakage)."""
    return f"{base}_{row_id}"


def _bsi_init_match_kind(
    session,
    sel_row,
    *,
    is_deposit: bool,
    kind_ids: list[str],
) -> str:
    key = _bsi_widget_key("bsi_match_kind", sel_row.id)
    if key not in st.session_state:
        st.session_state[key] = _bsi_default_match_kind(
            session,
            sel_row,
            is_deposit=is_deposit,
        )
    if st.session_state[key] not in kind_ids:
        st.session_state[key] = kind_ids[0]
    return st.session_state[key]


def _bsi_queue_row_summaries(session, postable) -> list[dict]:
    """Per-row queue metadata: id, summary line, kind label, confidence band."""
    rows: list[dict] = []
    for row in postable:
        is_deposit = bool(row.credit_amount and not row.debit_amount)
        is_withdrawal = bool(row.debit_amount and not row.credit_amount)
        sign = "+" if is_deposit else "-"
        summary = (
            f"#{row.import_row_index} · {row.date} · "
            f"{sign}{row.amount:,.2f} · {(row.description or '')[:40]}"
        )
        if is_deposit:
            kind_options = _bsi_deposit_kind_options(session)
        elif is_withdrawal:
            kind_options = _bsi_withdrawal_kind_options(session)
        else:
            rows.append(
                {
                    "row_id": row.id,
                    "summary": summary,
                    "kind_label": "—",
                    "confidence": "low",
                }
            )
            continue
        kind_labels = {k: _t(label_key) for k, label_key in kind_options}
        detected = _bsi_default_match_kind(session, row, is_deposit=is_deposit)
        kind_label = kind_labels.get(detected, kind_labels[kind_options[0][0]])
        confidence = _banking_match_kind_confidence(
            detected,
            row.description or "",
            is_deposit=is_deposit,
        )
        rows.append(
            {
                "row_id": row.id,
                "summary": summary,
                "kind_label": kind_label,
                "confidence": confidence,
                "date": row.date,
                "amount": round(float(row.amount), 2),
                "import_row_index": row.import_row_index,
            }
        )
    return rows


def _bsi_bank_fee_subtype_is_unambiguous(description: str) -> bool:
    """Subtype must match an explicit looks_like_* heuristic (not infer fallback alone)."""
    from reconciliation.match_post import (
        infer_bank_charge_subtype,
        looks_like_commission,
        looks_like_credit_card_account_fee,
        looks_like_interest,
        looks_like_transfer_fee,
    )

    desc = description or ""
    subtype = infer_bank_charge_subtype(desc)
    if subtype == "interest":
        return looks_like_interest(desc)
    if subtype == "credit_card_fee":
        return looks_like_credit_card_account_fee(desc)
    if subtype == "card_settlement_fee":
        return looks_like_commission(desc)
    if subtype == "transfer_fee":
        return looks_like_transfer_fee(desc)
    return False


def _bsi_bank_fee_description_is_mixed(description: str) -> bool:
    """Fee-like line that also matches another withdrawal classification."""
    from reconciliation.match_post import (
        looks_like_credit_card_bill_payment,
        looks_like_statement_bank_fee,
        looks_like_worker_payroll,
    )

    desc = description or ""
    if not looks_like_statement_bank_fee(desc):
        return False
    return looks_like_credit_card_bill_payment(desc) or looks_like_worker_payroll(desc)


def _bsi_bank_fee_batch_gl_ready(session, row) -> bool:
    imp = session.get(BankStatementImport, row.bank_statement_import_id)
    currency = imp.currency if imp else None
    charges = get_account_by_name(session, "Bank Charges")
    bank = get_account_by_name(session, "Bank", currency=currency)
    return bool(charges and bank)


def _bsi_bank_fee_batch_row_dict(session, row, *, review_reason: str | None = None) -> dict:
    from reconciliation.match_post import bank_charge_fee_label, infer_bank_charge_subtype

    desc = row.description or ""
    subtype = infer_bank_charge_subtype(desc)
    amt = round(float(row.amount), 2)
    return {
        "row_id": row.id,
        "import_row_index": row.import_row_index,
        "date": row.date,
        "description": desc,
        "amount": amt,
        "subtype": subtype,
        "subtype_label": bank_charge_fee_label(subtype),
        "account_impact": "Dr Bank Charges / Cr Bank",
        "label": (
            f"#{row.import_row_index} · {row.date} · "
            f"-{amt:,.2f} · {desc[:40]}"
        ),
        "review_reason": review_reason,
    }


def _bsi_bank_fee_batch_review_reason(session, cid: int, row) -> str | None:
    """None when batch-eligible; otherwise a stable review-reason code."""
    if not _bank_charges_on(session):
        return "bank_charges_disabled"
    if not (row.debit_amount and not row.credit_amount):
        return "not_withdrawal"
    if round(float(row.amount), 2) <= 0:
        return "invalid_amount"
    if row.status not in ("staging", "duplicate_flagged") or not row.parsed_successfully:
        return "not_postable"
    if _bsi_default_match_kind(session, row, is_deposit=False) != "bank_fee":
        return "not_bank_fee"
    if "bank_fee" not in banking_batch_eligible_kinds(session, cid):
        return "batch_kind_excluded"
    desc = row.description or ""
    if _bsi_bank_fee_description_is_mixed(desc):
        return "mixed_description"
    confidence = _banking_match_kind_confidence("bank_fee", desc, is_deposit=False)
    threshold = banking_batch_confidence_threshold(session, cid)
    if not banking_confidence_meets_batch_threshold(threshold, confidence):
        return "low_confidence"
    if not _bsi_bank_fee_subtype_is_unambiguous(desc):
        return "ambiguous_subtype"
    if not _bsi_bank_fee_batch_gl_ready(session, row):
        return "missing_gl_accounts"
    from reconciliation.match_post import infer_bank_charge_subtype

    subtype = infer_bank_charge_subtype(desc)
    if (
        "transfer_charges" in banking_review_required_kinds(session, cid)
        and subtype == "transfer_fee"
    ):
        return "review_required_transfer"
    return None


def _bsi_bank_fee_batch_partition(session, cid, postable) -> dict:
    """Split postable rows into batch-eligible vs needs-review (conservative)."""
    eligible: list[dict] = []
    needs_review: list[dict] = []
    for row in postable:
        reason = _bsi_bank_fee_batch_review_reason(session, cid, row)
        entry = _bsi_bank_fee_batch_row_dict(session, row, review_reason=reason)
        if reason:
            needs_review.append(entry)
        else:
            eligible.append(entry)
    return {"eligible": eligible, "needs_review": needs_review}


def _bsi_bank_fee_batch_candidates(session, cid, postable) -> list[dict]:
    """High-confidence bank_fee rows only — safe for unattended batch."""
    return _bsi_bank_fee_batch_partition(session, cid, postable)["eligible"]


def _bsi_execute_bank_fee_batch_post(
    session,
    cid: int,
    row_ids: list[int],
    user_id: int | None,
) -> list[dict]:
    """Loop post_bank_charge_outflow + log_audit; continue on per-row errors."""
    results: list[dict] = []
    for row_id in row_ids:
        row = session.get(BankStatementRow, row_id)
        label = f"#{row.import_row_index}" if row else str(row_id)
        if row is None:
            results.append(
                {
                    "row_id": row_id,
                    "label": label,
                    "status": "skipped",
                    "journal_entry_id": None,
                    "error": "not_postable",
                }
            )
            continue
        if row.status == "posted" or row.posted_journal_entry_id:
            results.append(
                {
                    "row_id": row_id,
                    "label": label,
                    "status": "already_posted",
                    "journal_entry_id": row.posted_journal_entry_id,
                    "error": None,
                }
            )
            continue
        review_reason = _bsi_bank_fee_batch_review_reason(session, cid, row)
        if review_reason:
            results.append(
                {
                    "row_id": row_id,
                    "label": label,
                    "status": "skipped",
                    "journal_entry_id": None,
                    "error": review_reason,
                }
            )
            continue
        try:
            result = post_bank_charge_outflow(
                session,
                row_id=row_id,
                company_id=cid,
                user_id=user_id,
            )
            log_audit(
                session,
                "Post",
                "BankStatementRow",
                row_id,
                f"Bank charge · {result['amount']:,.2f}",
            )
            results.append(
                {
                    "row_id": row_id,
                    "label": label,
                    "status": "posted",
                    "journal_entry_id": result.get("journal_entry_id"),
                    "error": None,
                }
            )
        except MatchPostError as exc:
            msg = str(exc)
            status = (
                "already_posted" if "already posted" in msg.lower() else "failed"
            )
            results.append(
                {
                    "row_id": row_id,
                    "label": label,
                    "status": status,
                    "journal_entry_id": None,
                    "error": msg,
                }
            )
        except ValueError as exc:
            results.append(
                {
                    "row_id": row_id,
                    "label": label,
                    "status": "failed",
                    "journal_entry_id": None,
                    "error": str(exc),
                }
            )
    return results


@st.fragment
def _bsi_match_queue_detail_fragment(session, cid: int, sel_row) -> None:
    """Fragment wrapper — body is testable without Streamlit fragment decorator."""
    _bsi_match_queue_detail_body(session, cid, sel_row)


def _bsi_match_queue_detail_body(session, cid: int, sel_row) -> None:
    is_deposit = bool(sel_row.credit_amount and not sel_row.debit_amount)
    is_withdrawal = bool(sel_row.debit_amount and not sel_row.credit_amount)

    st.markdown(f"**{_t('banking.import.match.queue_detail')}**")
    _render_bsi_match_line_summary(sel_row)

    if is_deposit:
        kind_options = _bsi_deposit_kind_options(session)
    elif is_withdrawal:
        kind_options = _bsi_withdrawal_kind_options(session)
    else:
        st.warning(_t("banking.import.match.unclear_amount"))
        return

    kind_ids = [k for k, _ in kind_options]
    kind_labels = {k: _t(label_key) for k, label_key in kind_options}
    match_kind = _bsi_init_match_kind(
        session,
        sel_row,
        is_deposit=is_deposit,
        kind_ids=kind_ids,
    )

    detected_kind = _bsi_default_match_kind(
        session,
        sel_row,
        is_deposit=is_deposit,
    )
    confidence = _banking_match_kind_confidence(
        detected_kind,
        sel_row.description or "",
        is_deposit=is_deposit,
    )
    uid = (_current_user() or {}).get("id")
    if banking_show_accounting_previews(session, cid, user_id=uid):
        preview = banking_accounting_preview(
            detected_kind,
            description=sel_row.description or "",
        )
        if preview:
            st.caption(_t("banking.import.match.accounting_preview", impact=preview))
    if detected_kind in kind_labels and banking_show_confidence_chips(
        session, cid, user_id=uid
    ):
        kind_key = _bsi_widget_key("bsi_match_kind", sel_row.id)
        _render_banking_match_suggestion_chip(
            detected_kind=detected_kind,
            kind_label=kind_labels[detected_kind],
            confidence=confidence,
            accept_key=f"bsi_accept_kind_{sel_row.id}",
            kind_state_key=kind_key,
        )

    match_kind = st.radio(
        _t("banking.import.match.what_is_this"),
        options=kind_ids,
        format_func=lambda k: kind_labels[k],
        key=_bsi_widget_key("bsi_match_kind", sel_row.id),
        horizontal=True,
    )
    st.divider()
    if match_kind == "card_clearing":
        _render_bsi_deposit_clearing(session, sel_row, cid)
    elif match_kind == "other_income":
        _render_bsi_other_deposit(session, sel_row, cid)
    elif match_kind == "equity_loan":
        _render_bsi_partner_owner_loan_match(
            session,
            sel_row=sel_row,
            cid=cid,
            is_deposit=is_deposit,
        )
    elif match_kind == "vendor":
        _render_bsi_vendor_payment(session, sel_row, cid)
    elif match_kind == "worker_payroll":
        _render_bsi_worker_payroll(session, sel_row, cid)
    elif match_kind == "cc_bill":
        _render_bsi_cc_bill(
            session,
            sel_row,
            cid,
            sel_row.description or "",
        )
    elif match_kind == "bank_fee":
        _render_bsi_bank_fee(session, sel_row, cid)


def _render_bsi_deposit_clearing(session, sel_row, cid: int) -> None:
    if not _card_settlement_on(session):
        st.caption(_t("banking.import.match.needs_settlement"))
        return
    st.info(_t("banking.import.match.pos_settlement_explainer"))
    st.caption(_t("banking.import.match.pos_bank_note"))
    _dep_style = card_deposit_style(sel_row.description or "")
    if _dep_style == "net":
        st.caption(_t("banking.import.match.net_sales_deposit_hint"))
    elif _dep_style == "gross":
        st.caption(_t("banking.import.match.pesin_sales_deposit_hint"))
    elif _dep_style == "card":
        st.caption(_t("banking.import.match.card_deposit_generic_hint"))
    settings = load_settings()
    currency = settings.get("currency", "TRY")
    clearing_acct = get_account_by_name(session, "Card Sales Clearing")
    available_clearing = (
        calculate_account_balance(session, clearing_acct) if clearing_acct else 0.0
    )
    deposit_amt = round(float(sel_row.amount), 2)
    unsettled_all = fetch_unsettled_card_sales_for_visibility(
        session,
        cid,
        get_unsettled_card_sales=get_unsettled_card_sales,
        get_account_by_name=get_account_by_name,
    )
    win_start = (sel_row.date or datetime.date.today()) - datetime.timedelta(days=7)
    win_end = (sel_row.date or datetime.date.today()) + datetime.timedelta(days=7)
    clearing = get_unsettled_card_sales(
        session,
        cid,
        date_from=win_start,
        date_to=win_end,
        get_account_by_name=get_account_by_name,
    )
    picked_sales: list = []
    sel_total_r = 0.0
    settlement_row_id = None
    confirm_inferred_fee = False
    preview_fee: float | None = None
    if clearing:
        sale_labels = {
            c["sale_id"]: (
                f"#{c['sale_id']} · {c['date']} · "
                f"{c['amount']:,.2f} · {c['invoice']}"
            )
            for c in clearing
        }
        picked_sales = st.multiselect(
            _t("banking.import.match.clearing_sales"),
            options=list(sale_labels.keys()),
            format_func=lambda i: sale_labels[i],
            key=_bsi_widget_key("bsi_match_sales", sel_row.id),
        )
        sel_total = sum(c["amount"] for c in clearing if c["sale_id"] in picked_sales)
        sel_total_r = round(sel_total, 2)
        fee_gap = round(sel_total_r - deposit_amt, 2)
        st.caption(
            _t(
                "banking.import.match.clearing_sum",
                total=f"{sel_total_r:,.2f}",
                deposit=f"{deposit_amt:,.2f}",
            )
        )
        if sel_row.date and abs(fee_gap) > 0.01 and fee_gap > 0:
            if _bank_charges_on(session):
                st.warning(
                    _t("banking.import.match.fee_gap", fee=f"{fee_gap:,.2f}")
                )
                matching_stl = get_matching_settlement_rows(
                    session, cid, sel_row.date, deposit_amt,
                )
                if matching_stl:
                    stl_labels = {
                        r.id: (
                            f"#{r.import_row_index} · {r.date} · "
                            f"gross {r.gross_amount:,.2f} · "
                            f"fee {r.fee_amount:,.2f} · "
                            f"net {r.net_amount:,.2f}"
                        )
                        for r in matching_stl
                    }
                    settlement_row_id = st.selectbox(
                        _t("banking.import.match.settlement_batch"),
                        options=[None] + list(stl_labels.keys()),
                        format_func=lambda i: (
                            _t("banking.import.match.no_settlement_batch")
                            if i is None
                            else stl_labels[i]
                        ),
                        key=_bsi_widget_key("bsi_match_settlement", sel_row.id),
                    )
                    if settlement_row_id:
                        stl_row = session.get(SettlementStatementRow, settlement_row_id)
                        if stl_row:
                            preview_fee = round(float(stl_row.fee_amount), 2)
                if not settlement_row_id:
                    confirm_inferred_fee = st.checkbox(
                        _t(
                            "banking.import.match.confirm_fee",
                            fee=f"{fee_gap:,.2f}",
                        ),
                        key=_bsi_widget_key("bsi_confirm_fee", sel_row.id),
                    )
            else:
                st.caption(_t("banking.import.match.needs_bank_charges"))
        elif fee_gap < -0.01:
            st.warning(_t("banking.import.match.deposit_over_clearing"))
        elif picked_sales and abs(fee_gap) <= 0.01 and sel_total_r > 0:
            st.caption(_t("banking.import.match.gross_deposit_hint"))
    else:
        st.caption(_t("banking.import.match.no_rows"))

    preview = compute_pos_settlement_preview(
        available_clearing,
        sel_total_r,
        deposit_amt,
        fee_amount=preview_fee,
    )
    _render_pos_settlement_preview_block(preview, currency)
    _bsi_imp = session.get(BankStatementImport, sel_row.bank_statement_import_id)
    _import_currency = _bsi_imp.currency if _bsi_imp else None
    _charges_acct = get_account_by_name(session, "Bank Charges")
    _fee_gap_needs_confirm = bool(
        picked_sales
        and sel_total_r > deposit_amt + 0.01
        and _bank_charges_on(session)
        and not settlement_row_id
    )
    _match_check = evaluate_pos_match_failure(
        sel_row=sel_row,
        preview=preview,
        deposit_amount=deposit_amt,
        picked_sale_count=len(picked_sales),
        unsettled_sales_available=bool(unsettled_all),
        window_sales_available=bool(clearing),
        bank_charges_enabled=_bank_charges_on(session),
        bank_charges_account_exists=_charges_acct is not None,
        confirm_inferred_fee=confirm_inferred_fee,
        fee_gap_needs_confirm=_fee_gap_needs_confirm,
        import_currency=_import_currency,
        company_currency=currency,
    )
    _render_pos_match_failure_block(_match_check, currency)
    visibility = _render_card_sales_clearing_visibility_block(
        session,
        cid,
        clearing_acct=clearing_acct,
        currency=currency,
    )
    if visibility is not None:
        _render_unsettled_card_sales_list_block(
            session,
            cid,
            currency=currency,
            visibility_unsettled_total=visibility.unsettled_card_sales_total,
        )

    if not clearing:
        return
    if st.button(
        _t("banking.import.match.post_clearing"),
        type="primary",
        key=_bsi_widget_key("bsi_post_clearing", sel_row.id),
    ):
        uid = (_current_user() or {}).get("id")
        try:
            post_deposit_clearing_match(
                session,
                row_id=sel_row.id,
                company_id=cid,
                sale_ids=picked_sales,
                user_id=uid,
                settlement_row_id=settlement_row_id,
                confirm_inferred_fee=confirm_inferred_fee,
            )
            log_audit(
                session,
                "Post",
                "BankStatementRow",
                sel_row.id,
                f"Clearing match · {sel_row.amount:,.2f}",
            )
            st.success(
                _t(
                    "banking.import.match.posted_ok",
                    row=sel_row.import_row_index,
                )
            )
            st.rerun()
        except (MatchPostError, ValueError) as exc:
            _bsi_render_statement_post_error(exc)


def _render_bsi_other_deposit(session, sel_row, cid: int) -> None:
    _common_credit_opts = [
        "Other Income",
        "Accounts Receivable",
        "Office Expense",
    ]
    credit_acct = st.selectbox(
        _t("banking.import.match.credit_account"),
        _common_credit_opts,
        key=_bsi_widget_key("bsi_match_credit_acct", sel_row.id),
    )
    with st.expander(_t("banking.import.match.other_income.advanced")):
        st.caption(_t("banking.import.match.other_income.advanced_hint"))
        use_sales_revenue = st.checkbox(
            _t("banking.import.match.other_income.use_sales_revenue"),
            key=_bsi_widget_key("bsi_other_income_use_sales_revenue", sel_row.id),
        )
    if use_sales_revenue:
        credit_acct = "Sales Revenue"
        st.warning(_t("banking.import.match.other_income.sales_revenue_warning"))
        if card_deposit_style(sel_row.description or ""):
            st.warning(_t("banking.import.match.other_income.sales_revenue_pos_warning"))
    if st.button(
        _t("banking.import.match.post_deposit"),
        type="primary",
        key=_bsi_widget_key("bsi_post_deposit", sel_row.id),
    ):
        uid = (_current_user() or {}).get("id")
        try:
            post_generic_deposit(
                session,
                row_id=sel_row.id,
                company_id=cid,
                credit_account_name=credit_acct,
                user_id=uid,
            )
            log_audit(
                session,
                "Post",
                "BankStatementRow",
                sel_row.id,
                f"Deposit · {sel_row.amount:,.2f} · CR {credit_acct}",
            )
            st.success(
                _t(
                    "banking.import.match.posted_ok",
                    row=sel_row.import_row_index,
                )
            )
            st.rerun()
        except (MatchPostError, ValueError) as exc:
            _bsi_render_statement_post_error(exc)


