    st.markdown(
        financial_statement_table_html(
            [
                ("Code", "Code", "code"),
                ("Account", "Account", "name"),
                ("Type", "Type", "text"),
                ("Current Balance", "Current Balance", "amount"),
                ("Active", "Active", "text"),
            ],
            data,
        ),
        unsafe_allow_html=True,
    )
    render_export_buttons(pd.DataFrame(data), "Chart_of_Accounts")

    st.markdown("---")
