def render_profit_loss(session, start_date=None, end_date=None):
    settings = load_settings()
    company  = settings.get("company_name", "My Company")
    currency = settings.get("currency", "USD")

    today = datetime.date.today()
    if start_date is None:
        start_date = datetime.date(today.year, 1, 1)
    if end_date is None:
        end_date = today

    stmt = compute_profit_loss_report(session, start_date=start_date, end_date=end_date)
    income_rows = [
        {"Code": ln.code, "Account": ln.account_name, "Amount": ln.amount}
        for ln in stmt.income_lines
    ]
    expense_rows = [
        {"Code": ln.code, "Account": ln.account_name, "Amount": ln.amount}
        for ln in stmt.expense_lines
    ]
    total_income = stmt.total_income
    total_expenses = stmt.total_expenses
    net = stmt.net
    margin_pct = stmt.margin_pct
    is_profit = stmt.is_profit

    # ── Banner ────────────────────────────────────────────────────────────────
    st.markdown(
        page_report_banner_html(
            f"📈 {_t('pnl.title')}",
            subtitle=f"{start_date.strftime('%d %b %Y')} — {end_date.strftime('%d %b %Y')}",
            meta=company,
            meta_sub=_t("pnl.generated", date=today.strftime("%d %b %Y")),
        ),
        unsafe_allow_html=True,
    )

    # ── KPI summary cards ─────────────────────────────────────────────────────
    pl_items = [
        {"label": _t("pnl.total_income"), "value": f"{currency} {total_income:,.2f}", "variant": "success", "sub": _t("pnl.accounts_count", count=len(income_rows))},
        {"label": _t("pnl.total_expenses"), "value": f"{currency} {total_expenses:,.2f}", "variant": "danger", "sub": _t("pnl.accounts_count", count=len(expense_rows))},
        {"label": (_t("pnl.net_profit") if is_profit else _t("pnl.net_loss")), "value": f"{currency} {abs(net):,.2f}", "variant": ("success" if is_profit else "danger"), "sub": _t("form.margin", pct=margin_pct)},
    ]
    render_kpi_grid(pl_items)

    st.markdown("<div style='margin-bottom:14px;'></div>", unsafe_allow_html=True)

    # ── Income section card ───────────────────────────────────────────────────
    with st.container(border=True):
        st.markdown(
            financial_section_header_html(
                _t("pnl.income_section"),
                f"{currency} {total_income:,.2f}",
                accent="success",
            ),
            unsafe_allow_html=True,
        )
        if income_rows:
            _render_fin_code_name_amount(income_rows)
        else:
            st.info(_t("pnl.no_income"))

    # ── Expense section card ──────────────────────────────────────────────────
    with st.container(border=True):
        st.markdown(
            financial_section_header_html(
                _t("pnl.expense_section"),
                f"{currency} {total_expenses:,.2f}",
                accent="danger",
            ),
            unsafe_allow_html=True,
        )
        if expense_rows:
            _render_fin_code_name_amount(expense_rows)
        else:
            st.info(_t("pnl.no_expenses"))

    # ── Net result banner ─────────────────────────────────────────────────────
    net_label         = _t("pnl.net_profit") if net > 0 else (_t("pnl.net_loss") if net < 0 else _t("pnl.break_even"))
    net_variant       = "success" if is_profit else ("danger" if net < 0 else "neutral")
    st.markdown(
        mobile_highlight_banner_html(
            net_label,
            f"{currency} {abs(net):,.2f}",
            subtitle=_t("form.margin", pct=margin_pct),
            variant=net_variant,
        ),
        unsafe_allow_html=True,
    )

    st.markdown("<div style='margin-top:12px;'></div>", unsafe_allow_html=True)
    export_rows = (
        [{"Section": _t("pnl.income_section"),  "Code": r["Code"], "Account": r["Account"], "Amount": r["Amount"]} for r in income_rows]
        + [{"Section": _t("pnl.total_income"),  "Code": "", "Account": "", "Amount": round(total_income, 2)}]
        + [{"Section": _t("pnl.expense_section"), "Code": r["Code"], "Account": r["Account"], "Amount": r["Amount"]} for r in expense_rows]
        + [{"Section": _t("pnl.total_expenses"), "Code": "", "Account": "", "Amount": round(total_expenses, 2)}]
        + [{"Section": _t("pnl.net_profit_loss"), "Code": "", "Account": "", "Amount": net}]
    )
    render_export_buttons(pd.DataFrame(export_rows), "Profit_Loss")


def render_balance_sheet(session, end_date=None):
    settings = load_settings()
    company  = settings.get("company_name", "My Company")
    currency = settings.get("currency", "USD")

    today = datetime.date.today()
    as_of = end_date if end_date is not None else today
    stmt = compute_balance_sheet_report(session, end_date=as_of)

    asset_rows = [
        {"Code": ln.code, "Account": ln.account_name, "Amount": ln.amount}
        for ln in stmt.asset_lines
    ]
    liability_rows = [
        {"Code": ln.code, "Account": ln.account_name, "Amount": ln.amount}
        for ln in stmt.liability_lines
    ]
    equity_rows = [
        {"Code": ln.code, "Account": ln.account_name, "Amount": ln.amount}
        for ln in stmt.equity_lines
    ]
    net_income = stmt.net_income
    total_assets = stmt.total_assets
    total_liabilities = stmt.total_liabilities
    total_equity = stmt.total_equity
    diff = stmt.imbalance
    balanced = stmt.balanced

    # ── Banner ────────────────────────────────────────────────────────────────
    st.markdown(
        page_report_banner_html(
            f"⚖️ {_t('bs.title')}",
            subtitle=_t("bs.as_of", date=as_of.strftime("%d %b %Y")),
            meta=company,
            meta_sub=_t("pnl.generated", date=today.strftime("%d %b %Y")),
        ),
        unsafe_allow_html=True,
    )

    # ── KPI row ───────────────────────────────────────────────────────────────
    bs_items = [
        {"label": _t("bs.total_assets"), "value": f"{currency} {total_assets:,.2f}"},
        {"label": _t("bs.total_liabilities"), "value": f"{currency} {total_liabilities:,.2f}"},
        {"label": _t("bs.equity_ni"), "value": f"{currency} {total_equity:,.2f}"},
    ]
    render_kpi_grid(bs_items)

    st.markdown("<div style='margin-bottom:14px;'></div>", unsafe_allow_html=True)

    def _bs_section(accent, title, total, rows):
        with st.container(border=True):
            st.markdown(
                financial_section_header_html(title, f"{currency} {total:,.2f}", accent=accent),
                unsafe_allow_html=True,
            )
            if rows:
                _render_fin_code_name_amount(rows)
            else:
                st.caption(_t("bs.no_accounts"))

    col_left, col_right = st.columns(2)
    with col_left:
        _bs_section("info", _t("bs.assets"), total_assets, asset_rows)
    with col_right:
        _bs_section("warning", _t("bs.liabilities"), total_liabilities, liability_rows)
        st.markdown("<div style='margin-bottom:8px;'></div>", unsafe_allow_html=True)
        equity_display = equity_rows + [{"Code": "—", "Account": _t("bs.net_income_line"), "Amount": round(net_income, 2)}]
        _bs_section("info", _t("bs.equity_ni"), total_equity, equity_display)

    # ── Balanced badge ────────────────────────────────────────────────────────
    badge_style = (
        "background:color-mix(in srgb,var(--theme-success) 16%,var(--theme-card) 84%);color:var(--theme-success-text);"
        if balanced else
        "background:color-mix(in srgb,var(--theme-danger) 16%,var(--theme-card) 84%);color:var(--theme-danger-text);"
    )
    badge_text  = (
        f"✅ {_t('bs.balanced')}" if balanced
        else f"❌ {_t('bs.imbalance', amount=f'{currency} {diff:,.2f}')}"
    )
    st.markdown(
        f'<div style="{badge_style}border-radius:99px;padding:8px 18px;font-size:12px;'
        f'font-weight:700;display:inline-block;margin-top:8px;">{badge_text}</div>',
        unsafe_allow_html=True,
    )
    st.markdown("<div style='margin-top:12px;'></div>", unsafe_allow_html=True)

    export_rows = (
        [{"Section": _t("bs.assets"),     "Code": r["Code"], "Account": r["Account"], "Amount": r["Amount"]} for r in asset_rows]
        + [{"Section": _t("bs.total_assets"),      "Code": "", "Account": "", "Amount": total_assets}]
        + [{"Section": _t("bs.liabilities"), "Code": r["Code"], "Account": r["Account"], "Amount": r["Amount"]} for r in liability_rows]
        + [{"Section": _t("bs.total_liabilities"), "Code": "", "Account": "", "Amount": total_liabilities}]
        + [{"Section": _t("bs.equity_gl"), "Code": r["Code"], "Account": r["Account"], "Amount": r["Amount"]} for r in equity_rows]
        + [{"Section": _t("bs.net_income_line"), "Code": "—", "Account": _t("bs.net_income_line"), "Amount": round(net_income, 2)}]
        + [{"Section": _t("bs.total_equity_ni"),  "Code": "", "Account": "", "Amount": total_equity}]
    )
    render_export_buttons(pd.DataFrame(export_rows), "Balance_Sheet")


def render_cash_flow(session, start_date=None, end_date=None):
    settings = load_settings()
    company  = settings.get("company_name", "My Company")
    currency = settings.get("currency", "USD")

    today = datetime.date.today()
    if start_date is None:
        start_date = datetime.date(today.year, 1, 1)
    if end_date is None:
        end_date = today

    stmt = compute_cash_flow_report(session, start_date=start_date, end_date=end_date)
    if not stmt.has_cash_accounts:
        st.warning(_t("cf.no_cash_bank"))
        return

    operating_rows = [
        {
            "Date": r.date,
            "Description": r.description,
            "Type": r.type,
            "Inflow": r.inflow,
            "Outflow": r.outflow,
        }
        for r in stmt.operating_rows
    ]
    financing_rows = [
        {
            "Date": r.date,
            "Description": r.description,
            "Type": r.type,
            "Inflow": r.inflow,
            "Outflow": r.outflow,
        }
        for r in stmt.financing_rows
    ]
    op_in = stmt.op_in
    op_out = stmt.op_out
    fin_in = stmt.fin_in
    fin_out = stmt.fin_out
    net_op = stmt.net_op
    net_fin = stmt.net_fin
    net_total = stmt.net_total

    # ── Banner ────────────────────────────────────────────────────────────────
    st.markdown(
        page_report_banner_html(
            f"💧 {_t('cf.title')}",
            subtitle=f"{start_date.strftime('%d %b %Y')} — {end_date.strftime('%d %b %Y')}",
            meta=company,
            meta_sub=_t("pnl.generated", date=today.strftime("%d %b %Y")),
        ),
        unsafe_allow_html=True,
    )

    # ── KPI row ───────────────────────────────────────────────────────────────
    def _cf_kpi(label, value):
        sign = "+" if value > 0 else ""
        variant = "amt-zero"
        if value > 0:
            variant = "amt-pos"
        elif value < 0:
            variant = "amt-neg"
        return mobile_kpi_chip_html(label, f"{sign}{currency} {value:,.2f}", variant=variant)

    with st.container(border=False, key="mob_rpt_cf_kpi"):
        st.markdown(
            mobile_kpi_grid_html(
                _cf_kpi(_t("cf.net_operating"), net_op),
                _cf_kpi(_t("cf.net_financing"), net_fin),
                _cf_kpi(_t("cf.net_change"), net_total),
            ),
            unsafe_allow_html=True,
        )

    st.markdown("<div style='margin-bottom:14px;'></div>", unsafe_allow_html=True)

    def _cf_rows_html(rows):
        buf = ""
        for r in rows:
            date_str = r["Date"].strftime("%d %b") if hasattr(r["Date"], "strftime") else str(r["Date"])
            desc = html.escape(str(r["Description"] or ""))
            typ = html.escape(str(r["Type"] or ""))
            if r["Inflow"]:
                amt = f'<span class="erp-fin-cf-amt amt-pos">+{currency} {r["Inflow"]:,.2f}</span>'
            elif r["Outflow"]:
                amt = f'<span class="erp-fin-cf-amt amt-neg">−{currency} {r["Outflow"]:,.2f}</span>'
            else:
                amt = '<span class="erp-fin-cf-amt">—</span>'
            buf += (
                f'<div class="erp-fin-cf-row">'
                f'<span class="erp-fin-cf-date">{html.escape(date_str)}</span>'
                f'<span class="erp-fin-cf-desc">{desc}</span>'
                f'<span class="erp-fin-cf-type">{typ}</span>'
                f"{amt}</div>"
            )
        return buf

    # ── Operating section card ────────────────────────────────────────────────
    with st.container(border=True):
        st.markdown(
            financial_section_header_html(
                _t("cf.operating"),
                subtitle=_t("cf.in_out", inflow=f"{currency} {op_in:,.2f}", outflow=f"{currency} {op_out:,.2f}"),
                accent="success",
            ),
            unsafe_allow_html=True,
        )
        if operating_rows:
            st.markdown(_cf_rows_html(operating_rows), unsafe_allow_html=True)
        else:
            st.caption(_t("cf.no_operating"))

    # ── Financing section card ────────────────────────────────────────────────
    with st.container(border=True):
        st.markdown(
            financial_section_header_html(
                _t("cf.financing"),
                subtitle=_t("cf.in_out", inflow=f"{currency} {fin_in:,.2f}", outflow=f"{currency} {fin_out:,.2f}"),
                accent="info",
            ),
            unsafe_allow_html=True,
        )
        if financing_rows:
            st.markdown(_cf_rows_html(financing_rows), unsafe_allow_html=True)
        else:
            st.caption(_t("cf.no_financing"))

    # ── Net change banner ─────────────────────────────────────────────────────
    nc_sign   = "+" if net_total >= 0 else "−"
    st.markdown(
        mobile_highlight_banner_html(
            _t("cf.net_change_banner"),
            f"{nc_sign}{currency} {abs(net_total):,.2f}",
            subtitle=_t("cf.operating_plus_financing"),
            variant="success" if net_total >= 0 else "danger",
        ),
        unsafe_allow_html=True,
    )

    st.markdown("<div style='margin-top:12px;'></div>", unsafe_allow_html=True)
    export_rows = (
        [{"Section": _t("cf.operating"), **r} for r in operating_rows]
        + [{"Section": _t("cf.net_operating"),  "Date": "", "Description": "", "Type": "", "Inflow": net_op,    "Outflow": 0.0}]
        + [{"Section": _t("cf.financing"), **r} for r in financing_rows]
        + [{"Section": _t("cf.net_financing"),  "Date": "", "Description": "", "Type": "", "Inflow": net_fin,   "Outflow": 0.0}]
        + [{"Section": _t("cf.net_change"),     "Date": "", "Description": "", "Type": "",
            "Inflow": net_total if net_total >= 0 else 0.0,
            "Outflow": round(-net_total, 2) if net_total < 0 else 0.0}]
    )
    render_export_buttons(pd.DataFrame(export_rows), "Cash_Flow")


# ═══════════════════════════════════════════════════════════════════════════════
